INSERT INTO `products` (`id`, `name`, `slug`, `code`, `product_category_id`, `manufacturer_id`, `description`, `image`, `price_prime`, `price`, `unit_id`, `price_sale`, `quantity`, `admin_id`, `bought`, `view_count`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Son Kem Nhung', 'son-kem-nhung-1717235954', 'SP0001', 1, 178, '<h2 dir=\"ltr\">Th&agrave;nh phần son Kem Nhung</h2>\r\n\r\n<p dir=\"ltr\">Son Kem Nhung Cỏ Mềm c&oacute; chứa c&aacute;c th&agrave;nh phần từ thi&ecirc;n nhi&ecirc;n như:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sclerocarya birrea seed oil (and) tetradecane</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Isododecane</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sorbitan Olivate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">M&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hydrogenated Polycyclopentadiene</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Copernicia Cerifera (Carnauba) Wax</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Boron Nitride</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Butyrospermum parkii (shea) butter (Bơ Hạt mỡ)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tocopherol (Vitamin E)</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\">&nbsp;</p>\r\n\r\n<h2>Hướng dẫn sử dụng</h2>\r\n\r\n<p>T&ocirc; một lớp mỏng l&ecirc;n m&ocirc;i cho gương mặt tươi tắn, rạng ngời.</p>\r\n\r\n<p>Sau 15-20 ph&uacute;t dưỡng chất sẽ thấm mềm v&agrave;o da m&ocirc;i khiến son mỏng mịn tự nhi&ecirc;n.</p>\r\n\r\n<p>C&oacute; thể sử d&ugrave;ng k&egrave;m son dưỡng ẩm cho m&ocirc;i nếu ở l&acirc;u trong ph&ograve;ng điều h&ograve;a.</p>', '171723595420240601165914d4TaRnjkhobx6aGwsGGdJqdA5kSBtuCjSbHwoRSZ.webp', 100.00, 160.00, 16, 160.00, 987, 1, 5, 3, 1, '2024-06-01 09:59:14', '2024-06-09 17:13:28'),
(2, 'Dầu Gội Thảo Dược Tóc Mây', 'dau-goi-thao-duoc-toc-may-1717356239', 'SP002', 3, 19, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p><em>Với chiết xuất từ Bồ kết v&agrave; thảo dược truyền thống c&ugrave;ng c&aacute;c hoạt chất thi&ecirc;n nhi&ecirc;n,&nbsp;<strong>Dầu gội thảo dược T&oacute;c M&acirc;y</strong>&nbsp;gi&uacute;p l&agrave;m sạch t&oacute;c v&agrave; da đầu, ngăn ngừa v&agrave; cải thiện t&igrave;nh trạng t&oacute;c g&agrave;u, g&atilde;y rụng, chẻ ngọn. Sản phẩm c&oacute; thể d&ugrave;ng cho mẹ bầu v&agrave; cả những người c&oacute; da đầu nhạy cảm.</em></p>\r\n\r\n<p><img alt=\"dầu gội thảo dược tóc mây\" src=\"https://static.comem.vn/uploads/August2023/dau-goi-thao-duoc-toc-may-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p><em>Dầu gội thảo dược T&oacute;c M&acirc;y Cỏ Mềm</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"height:20px; width:500px\">\r\n	<tbody>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Dầu gội thảo dược T&oacute;c M&acirc;y</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng</td>\r\n			<td>300 gram</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Vấn đề của t&oacute;c</td>\r\n			<td>T&oacute;c xơ, g&agrave;u, g&atilde;y rụng nhiều</td>\r\n		</tr>\r\n		<tr>\r\n			<td>C&ocirc;ng dụng</td>\r\n			<td>L&agrave;m sạch t&oacute;c, da đầu, ngăn ngừa cải thiện t&igrave;nh trạng g&agrave;u, g&atilde;y rụng, chẻ ngọn cho m&aacute;i t&oacute;c mềm mượt, chắc khoẻ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>M&ugrave;i hương</td>\r\n			<td>Hương thơm dịu nhẹ với m&ugrave;i thảo dược tự nhi&ecirc;n</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật dầu gội thảo dược T&oacute;c M&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Dầu gội thảo dược T&oacute;c M&acirc;y được người ti&ecirc;u d&ugrave;ng đ&aacute;nh gi&aacute; cao bởi sản phẩm kh&ocirc;ng chứa silicon, kh&ocirc;ng sulfate n&ecirc;n rất an to&agrave;n cho b&agrave; bầu, phụ nữ c&oacute; thai v&agrave; người c&oacute; da đầu nhạy cảm. Với c&ocirc;ng thức kết hợp c&aacute;c loại thảo mộc truyền thống v&agrave; hoạt chất thi&ecirc;n nhi&ecirc;n hiện đại gi&uacute;p ph&aacute;t huy t&aacute;c dụng:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Bồ kết, Bồ h&ograve;n, Cỏ ngũ sắc:</strong>&nbsp;Chứa saponin gi&uacute;p tạo bọt tự nhi&ecirc;n, l&agrave;m sạch g&agrave;u</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Hương nhu v&agrave; Cỏ mần trầu:</strong>&nbsp;Sạch g&agrave;u, ngăn ngừa rụng t&oacute;c</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Tinh dầu vỏ Bưởi:</strong>&nbsp;G&oacute;p phần ngăn ngừa rụng t&oacute;c&nbsp;</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Tang bạch b&igrave;:</strong>&nbsp;Ngăn ngừa rụng t&oacute;c</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Tinh dầu Sả chanh:</strong>&nbsp;Mang hương thơm nhẹ nh&agrave;ng, gi&uacute;p đem lại cảm gi&aacute;c thư gi&atilde;n khi gội đầu</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Dầu quả Bơ:</strong>&nbsp;Chứa nhiều vitamin A, C, D, E l&agrave; một nguồn bổ sung tuyệt vời cho t&oacute;c kh&ocirc;, phục hồi t&oacute;c hư tổn, dưỡng t&oacute;c mềm mượt, chắc khỏe</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Protein từ đậu H&agrave; Lan</strong>&nbsp;(Cetearamidoethyldiethonium Succinoyl Hydrolyzed Pea Protein): C&oacute; khả năng thay thế silicone gi&uacute;p l&agrave;m mượt t&oacute;c, phục hồi t&oacute;c hư tổn m&agrave; kh&ocirc;ng g&acirc;y b&iacute;t tắc nang t&oacute;c.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"dầu gội thảo dược tóc mây\" src=\"https://static.comem.vn/uploads/August2023/dau-goi-thao-duoc-toc-may-1_94.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Dầu gội thảo dược T&oacute;c M&acirc;y kh&ocirc;ng chứa silicon v&agrave; sulfate</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng dầu gội thảo dược T&oacute;c M&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Dầu gội thảo dược T&oacute;c M&acirc;y được sử dụng gi&uacute;p l&agrave;m sạch t&oacute;c v&agrave; da đầu, ngăn ngừa v&agrave; cải thiện t&igrave;nh trạng t&oacute;c g&agrave;u, g&atilde;y rụng, chẻ ngọn, cho m&aacute;i t&oacute;c mềm mượt, chắc khỏe. Sản phẩm g&oacute;p phần k&iacute;ch th&iacute;ch sự ph&aacute;t triển của nang t&oacute;c.&nbsp;</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần của sản phẩm</h2>\r\n\r\n<p dir=\"ltr\">Dầu gội thảo dược T&oacute;c M&acirc;y kh&ocirc;ng chứa silicon, kh&ocirc;ng sulfate, an to&agrave;n cho cả những l&agrave;n da nhạy cảm nhất với sự kết hợp của:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Nước tinh khiết (Purified water)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Cao dược liệu: quả Bồ kết, rễ v&agrave; l&aacute; D&acirc;u Tằm, cỏ Mần Trầu, cỏ Ngũ Sắc, l&aacute; Tre, quả Mắc Kham, quả Bồ H&ograve;n</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Propanediol</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Glycerin</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu vỏ Bưởi (Citrus maxima peel essential oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Hương nhu (Ocimum gratissimum essential oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Sả chanh (Cymbopogon citratus essential oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu quả Bơ (Persea gratissima fruit oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Vitamin E (Tocopherol)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Phenoxyethanol.</p>\r\n	</li>\r\n</ul>', '171735669320240603023133Fk8uWaGLk6T7BwMIkIKInhNFwAHwLU8S5sbMvMsC.webp', 200.00, 325.00, 3, 325.00, 98, 1, 2, 3, 1, '2024-06-02 19:23:59', '2024-06-03 12:08:11'),
(3, 'Kem Dưỡng Ẩm Ngừa Lão Hóa Tơ Tằm', 'kem-duong-am-ngua-lao-hoa-to-tam-1717381846', 'SP003', 2, 278, '<h2>H&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p><em><strong>Kem dưỡng ẩm ngừa l&atilde;o h&oacute;a Tơ Tằm</strong>&nbsp;gi&uacute;p cấp ẩm v&agrave; cung cấp dưỡng chất cho da, gi&uacute;p giảm kh&ocirc; sần da, l&agrave;m chậm qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a da, ngăn ngừa nếp nhăn, hỗ trợ phục hồi l&agrave;n da v&agrave; gi&uacute;p duy tr&igrave; l&agrave;n da căng mịn. Sản phẩm ph&ugrave; hợp với mọi loại da, kể cả da nhạy cảm.</em></p>\r\n\r\n<p><img alt=\"kem dưỡng tơ tằm\" src=\"https://static.comem.vn/uploads/2024/04/kem-duong-am-ngua-lao-hoa-to-tam-4_8.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem dưỡng ẩm ngừa l&atilde;o ho&aacute; Tơ Tằm</p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Kem dưỡng ẩm ngừa l&atilde;o h&oacute;a Tơ Tằm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng</td>\r\n			<td>50 gram</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thể chất</td>\r\n			<td>Dạng kem mỏng nhẹ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Loại da ph&ugrave; hợp</td>\r\n			<td>Ph&ugrave; hợp với mọi loại da</td>\r\n		</tr>\r\n		<tr>\r\n			<td>M&ugrave;i hương</td>\r\n			<td>Hương thơm dịu nhẹ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thời điểm sử dụng</td>\r\n			<td>D&ugrave;ng 2 lần s&aacute;ng - tối sau khi l&agrave;m sạch da để c&oacute; hiệu quả tốt nhất</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng. Mở nắp: 6 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật kem dưỡng ẩm ngừa l&atilde;o h&oacute;a Tơ Tằm</h2>\r\n\r\n<p dir=\"ltr\">Kem dưỡng ẩm ngừa l&atilde;o h&oacute;a Tơ Tằm được nhiều người tin tưởng sử dụng bởi sản phẩm kh&ocirc;ng chứa silicone n&ecirc;n an to&agrave;n cho cả l&agrave;n da mẹ bầu v&agrave; những l&agrave;n da nhạy cảm nhất:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chứa Chiết xuất Tơ Tằm, Propanediol v&agrave; hyaluronic acid: Gi&uacute;p dưỡng ẩm, giảm kh&ocirc; sần da, l&agrave;m da mịn m&agrave;ng, mềm mại, cải thiện đ&aacute;ng kể độ đ&agrave;n hồi của da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hydrolyzed Sodium Hyaluronate l&agrave; HA c&oacute; k&iacute;ch thước ph&acirc;n tử nhỏ (dưới 130kDa): Gi&uacute;p cải thiện độ ẩm, độ đ&agrave;n hồi cho da, gi&uacute;p l&agrave;m mờ nếp nhăn tr&ecirc;n da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu hạt Hướng Dương: Tạo m&agrave;ng kh&oacute;a ẩm gi&uacute;p da kh&ocirc;ng mất nước, kh&ocirc;i phục h&agrave;ng r&agrave;o bảo vệ da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Ceramide c&oacute; cấu tr&uacute;c tương tự lớp lipid tr&ecirc;n da: Gi&uacute;p tăng cường dưỡng ẩm v&agrave; phục hồi h&agrave;ng r&agrave;o bảo vệ da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Ubiquinone (Coenzyme Q10): C&oacute; t&aacute;c dụng ngăn ngừa l&atilde;o ho&aacute; v&agrave; bảo vệ da khỏi t&aacute;c hại của tia UV.&nbsp;</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Protein Sữa ong ch&uacute;a (Hydrolyzed royal jelly protein): Gi&uacute;p hạn chế nếp nhăn tr&ecirc;n da, bảo vệ da khỏi &aacute;nh s&aacute;ng của tia UV.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Niacinamide 5%: Gi&uacute;p l&agrave;m mờ c&aacute;c vết th&acirc;m n&aacute;m, đốm đỏ hay sạm da đồng thời gi&uacute;p l&agrave;m chậm qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a da, giảm nếp nhăn v&agrave; cải thiện độ đ&agrave;n hồi của da.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"kem dưỡng ẩm ngừa lão hóa tơ tằm\" src=\"https://static.comem.vn/uploads/August2023/kem-duong-am-ngua-lao-hoa-to-tam-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem dưỡng ẩm Tơ Tằm c&oacute; nhiều ưu điểm nổi bật</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng kem dưỡng ẩm ngừa l&atilde;o h&oacute;a Tơ Tằm</h2>\r\n\r\n<p dir=\"ltr\">Kem dưỡng ẩm ngừa l&atilde;o h&oacute;a Tơ Tằm được sử dụng với t&aacute;c dụng cấp ẩm v&agrave; cung cấp dưỡng chất cho da, gi&uacute;p giảm kh&ocirc; sần da, l&agrave;m chậm qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a, g&oacute;p phần ngăn ngừa h&igrave;nh th&agrave;nh c&aacute;c nếp nhăn tr&ecirc;n da, hỗ trợ phục hồi da, gi&uacute;p duy tr&igrave; l&agrave;n da căng mịn. C&oacute; thể sử dụng sản phẩm cho mọi loại da, bao gồm cả da nhạy cảm.</p>\r\n\r\n<p><img alt=\"kem dưỡng ẩm ngừa lão hóa tơ tằm\" src=\"https://static.comem.vn/uploads/August2023/kem-duong-am-ngua-lao-hoa-to-tam-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>C&ocirc;ng dụng kem dưỡng ẩm ngừa l&atilde;o h&oacute;a Tơ Tằm</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần của kem dưỡng ẩm Tơ Tằm</h2>\r\n\r\n<p dir=\"ltr\">C&ugrave;ng kh&aacute;m ph&aacute; bảng th&agrave;nh phần kem dưỡng ẩm Tơ Tằm gi&uacute;p ngăn ngừa h&igrave;nh th&agrave;nh c&aacute;c nếp nhăn tr&ecirc;n da, cho l&agrave;n da căng mịn:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Purified water (Nước tinh khiết)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Propanediol</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Niacinamide</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Isododecane</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Coco- Caprylate/Caprate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Helianthus Annuus (Sunflower) Seed Oil (Dầu hạt Hướng Durong)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hydrolyzed royal jelly protein (Protein Sữa ong ch&uacute;a)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hydrolyzed silk (Chiết xuất Tơ tằm)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hyaluronic Acid</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hydrolyzed Sodium Hyaluronate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dipotassium glycyrrhizinate root extract (Chiết xuất rễ Cam Thảo)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sodium gluconate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Lavandula Angustifolia Essential Oil (Tinh dầu Oải Hương).</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em><strong>Kem dưỡng ẩm ngừa l&atilde;o h&oacute;a Tơ Tằm</strong>&nbsp;l&agrave; sản phẩm dưỡng da an to&agrave;n c&oacute; thể d&ugrave;ng cho l&agrave;n da nhạy cảm, mẹ bầu, bổ sung độ ẩm cho l&agrave;n da căng mịn, l&agrave;m chậm qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a. C&ograve;n chần chừ g&igrave; nữa m&agrave; kh&ocirc;ng li&ecirc;n hệ ngay với Cỏ để sở hữu ngay em dưỡng ẩm n&agrave;y n&agrave;o!</em></p>', '17173818462024060309304688SKWrwGNEOmI1v3kHSrzmHbXGvtggtGxMKvtJ1A.webp', 250.00, 315.00, 7, 300.00, 400, 1, 0, 1, 1, '2024-06-03 02:30:46', '2024-06-03 07:14:51'),
(4, 'Sữa Rửa Mặt Tạo Bọt Tơ Tằm', 'sua-rua-mat-tao-bot-to-tam-1717382172', 'SP004', 2, 22, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p><em><strong>Sữa rửa mặt tạo bọt Tơ Tằm</strong>&nbsp;l&agrave; sản phẩm gi&uacute;p l&agrave;m sạch da, duy tr&igrave; độ ẩm tự nhi&ecirc;n tr&ecirc;n da, gi&uacute;p sạch tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, cho l&agrave;n da tr&ocirc;ng s&aacute;ng sạch v&agrave; mịn m&agrave;ng hơn. Sản phẩm ph&ugrave; hợp với mọi loại da, kể cả da nhạy cảm.</em></p>\r\n\r\n<p><img alt=\"Sữa rửa mặt tạo bọt Tơ Tằm\" src=\"https://static.comem.vn/uploads/August2023/sua-rua-mat-tao-bot-to-tam-co-mem-4.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p><em>Sữa rửa mặt tạo bọt Tơ Tằm</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Sữa rửa mặt tạo bọt Tơ Tằm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dung t&iacute;ch</td>\r\n			<td>150ml</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thể chất</td>\r\n			<td>Dạng bọt mềm mại</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Độ pH</td>\r\n			<td>5.5</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Loại da ph&ugrave; hợp</td>\r\n			<td>Ph&ugrave; hợp với mọi loại da, kể cả da nhạy cảm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>M&ugrave;i hương</td>\r\n			<td>M&ugrave;i thơm dễ chịu, dịu nhẹ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>C&ocirc;ng dụng</td>\r\n			<td>L&agrave;m sạch da, duy tr&igrave; độ ẩm tự nhi&ecirc;n, sạch tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, da s&aacute;ng sạch, mịn m&agrave;ng</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng. Mở nắp: 12 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật sữa rửa mặt tạo bọt Tơ Tằm</h2>\r\n\r\n<p dir=\"ltr\">Sữa rửa mặt tạo bọt Tơ Tằm l&agrave; sản phẩm gi&uacute;p l&agrave;m sạch da, được nhiều t&iacute;n đồ l&agrave;m đẹp tin tưởng sử dụng trong chu tr&igrave;nh chăm s&oacute;c da h&agrave;ng ng&agrave;y với những ưu điểm nổi bật:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">C&aacute;c chất l&agrave;m sạch c&oacute; nguồn gốc thi&ecirc;n nhi&ecirc;n: Disodium Cocoyl Glutamate, Sodium Cocoamphoacetate, Coco Glucoside gi&uacute;p l&agrave;m sạch da dịu nhẹ m&agrave; kh&ocirc;ng g&acirc;y k&iacute;ch ứng cho da. Gi&uacute;p l&agrave;m sạch mịn m&agrave;ng sau khi sử dụng.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Độ pH gần với pH sinh l&yacute;, kh&ocirc;ng g&acirc;y k&iacute;ch ứng cho da nhạy cảm.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chứa Glycerin, Chiết xuất Tơ Tằm v&agrave; Hyaluronic Acid l&agrave; những chất dưỡng ẩm, gi&uacute;p giảm kh&ocirc; sần, cho l&agrave;n da mềm mại, mịn m&agrave;ng, kh&ocirc;ng bị kh&ocirc; căng sau khi sử dụng sản phẩm.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Panthenol (Vitamin B5): Gi&uacute;p dưỡng ẩm, l&agrave;m mềm, hạn chế sự mất nước qua biểu b&igrave; da sau khi d&ugrave;ng chất tẩy rửa gi&uacute;p da bớt kh&ocirc; sần, bong tr&oacute;c, k&iacute;ch ứng.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Betaine: l&agrave; một trong những yếu tố giữ ẩm tự nhi&ecirc;n tr&ecirc;n da (NMF) c&oacute; khả năng giữ ẩm mạnh, l&agrave;m dịu da, giảm khả năng k&iacute;ch ứng do chất tẩy rửa g&acirc;y ra, gi&uacute;p duy tr&igrave; h&agrave;ng r&agrave;o bảo vệ da.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"sữa rửa mặt tạo bọt tơ tằm\" src=\"https://static.comem.vn/uploads/August2023/sua-rua-mat-tao-bot-to-tam-co-mem-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Sữa rửa mặt Tơ Tằm pH 5.5</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng sữa rửa mặt Tơ Tằm nh&agrave; Cỏ</h2>\r\n\r\n<p>Sữa rửa mặt tạo bọt Tơ Tằm Cỏ Mềm được sử dụng để l&agrave;m sạch da, gi&uacute;p duy tr&igrave; độ ẩm tự nhi&ecirc;n tr&ecirc;n da, sạch tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, cho l&agrave;n da tr&ocirc;ng s&aacute;ng sạch v&agrave; mịn m&agrave;ng hơn. Sản phẩm c&oacute; thể d&ugrave;ng cho mọi loại da cũng như l&agrave;n da nhạy cảm.</p>\r\n\r\n<p><img alt=\"sữa rửa mặt tạo bọt tơ tằm\" src=\"https://static.comem.vn/uploads/August2023/sua-rua-mat-tao-bot-to-tam-co-mem-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Sữa rửa mặt tạo bọt Tơ Tằm cho l&agrave;n da s&aacute;ng sạch</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần sữa rửa mặt tạo bọt Tơ Tằm</h2>\r\n\r\n<p dir=\"ltr\">Sữa rửa mặt tạo bọt Tơ Tằm l&agrave; d&ograve;ng sữa rửa mặt c&oacute; thể sử dụng cho da nhạy cảm với c&aacute;c th&agrave;nh phần ch&iacute;nh bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Purified water (Nước tinh khiết)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Disodium Cocoyl Glutamate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sorbitol</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Glycerin</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sodium Cocoamphoacetate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Coco Glucoside</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Betaine</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Panthenol</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hyaluronic acid</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hydrolyzed silk (Chiết xuất Tơ Tằm)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Lavandula Angustifolia Essential Oil (Tinh dầu Oải Hương)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Citrus Aurantifolia Essential Oil (Tinh dầu Chanh)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Citric Acid (Acid Citric).</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"sữa rửa mặt tạo bọt tơ tằm\" src=\"https://static.comem.vn/uploads/August2023/sua-rua-mat-tao-bot-to-tam-co-mem-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Th&agrave;nh phần sữa rửa mặt an to&agrave;n cho da nhạy cảm</p>\r\n\r\n<p dir=\"ltr\"><em>Nếu bạn đang t&igrave;m kiếm một d&ograve;ng sữa rửa mặt tạo bọt gi&uacute;p l&agrave;m sạch da, duy tr&igrave; độ ẩm tự nhi&ecirc;n cho da m&agrave; kh&ocirc;ng g&acirc;y kh&ocirc; da, lại c&oacute; thể sử dụng cho da nhạy cảm, h&atilde;y tham khảo ngay<strong>&nbsp;sữa rửa mặt tạo bọt Tơ Tằm</strong>&nbsp;Cỏ Mềm bạn nh&eacute;!</em></p>', '171738217220240603093612j0f017m2gTWaOj1Flxxe18Ir4GdISBwI6k7BDtsD.webp', 70.00, 95.00, 3, 95.00, 70, 1, 0, 0, 1, '2024-06-03 02:36:12', '2024-06-03 02:37:06'),
(5, 'Nước Tẩy Trang Rau Má', 'nuoc-tay-trang-rau-ma-1717382434', 'SP005', 2, 40, '<p dir=\"ltr\"><em><strong>Nước Tẩy Trang Rau M&aacute;</strong>&nbsp;l&agrave; sản phẩm gi&uacute;p l&agrave;m sạch da, loại bỏ đi lớp trang điểm, bụi bẩn, dầu thừa tr&ecirc;n da, l&agrave;m th&ocirc;ng tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, gi&uacute;p duy tr&igrave; độ ẩm tự nhi&ecirc;n, cho l&agrave;n da mềm mại, s&aacute;ng sạch. Sản phẩm th&iacute;ch hợp cho da dầu, mụn, nhạy cảm v&agrave; sử dụng được cho cả v&ugrave;ng mắt v&agrave; m&ocirc;i.</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Nước tẩy trang Rau M&aacute;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dung t&iacute;ch</td>\r\n			<td>150ml</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Kết cấu</td>\r\n			<td>Dạng nước, dung dịch trong suốt</td>\r\n		</tr>\r\n		<tr>\r\n			<td>M&ugrave;i hương</td>\r\n			<td>Dịu nhẹ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Loại da ph&ugrave; hợp</td>\r\n			<td>Th&iacute;ch hợp cho da dầu mụn, da nhạy cảm, sử dụng được cho cả v&ugrave;ng mắt v&agrave; m&ocirc;i</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng. Mở nắp: 12 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật nước tẩy trang Rau M&aacute;</h2>\r\n\r\n<p dir=\"ltr\">Nước tẩy trang Rau M&aacute; l&agrave; sản phẩm l&agrave;m sạch da được nhiều người tin d&ugrave;ng bởi c&aacute;c ưu điểm nổi bật sau:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chiết xuất Rau m&aacute;: Gi&uacute;p cải thiện t&igrave;nh trạng mụn vi&ecirc;m v&agrave; giữ ẩm cho da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hyaluronic acid v&agrave; Chiết xuất l&aacute; Nha Đam: Gi&uacute;p dưỡng ẩm, giảm kh&ocirc; sần cho da, l&agrave;m da mịn m&agrave;ng, mềm mại, cải thiện độ đ&agrave;n hồi của da v&agrave; tăng khả năng hấp thu c&aacute;c dưỡng chất kh&aacute;c.&nbsp;</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Gluconolactone: Gi&uacute;p cải thiện t&igrave;nh trạng mụn tr&ecirc;n da (cả mụn vi&ecirc;m v&agrave; mụn kh&ocirc;ng vi&ecirc;m).</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu tr&agrave;m tr&agrave;: Gi&uacute;p kh&aacute;ng khuẩn v&agrave; cải thiện t&igrave;nh trạng mụn tr&ecirc;n da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu nghệ: Gi&uacute;p phục hồi da, l&agrave;m mờ c&aacute;c vết th&acirc;m sau mụn tr&ecirc;n da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Peg 8 Caprylic/ Capric Glycerides: Gi&uacute;p hạn chế t&igrave;nh trạng mẩn đỏ, kh&ocirc; r&aacute;t da.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"nước tẩy trang rau má\" src=\"https://static.comem.vn/uploads/August2023/nuoc-tay-trang-rau-ma-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Nước tẩy trang Rau M&aacute; gi&uacute;p l&agrave;m th&ocirc;ng tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng nước tẩy trang Rau M&aacute; Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Nước tẩy trang Rau M&aacute; l&agrave; sản phẩm nằm trong bộ chăm s&oacute;c da với chiết xuất rau m&aacute; nh&agrave; Cỏ gi&uacute;p l&agrave;m sạch da, loại bỏ đi lớp trang điểm, bụi bẩn, dầu thừa tr&ecirc;n da, l&agrave;m th&ocirc;ng tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, gi&uacute;p duy tr&igrave; độ ẩm tự nhi&ecirc;n cho da, cho l&agrave;n da mềm mại, s&aacute;ng sạch. Sản phẩm c&oacute; thể l&agrave;m sạch cho cả v&ugrave;ng mắt v&agrave; m&ocirc;i.</p>\r\n\r\n<p><img alt=\"nước tẩy trang rau má\" src=\"https://static.comem.vn/uploads/August2023/nuoc-tay-trang-rau-ma-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Nước tẩy trang Rau M&aacute; cho l&agrave;n da mềm mại, s&aacute;ng sạch</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần nước tẩy trang Rau M&aacute;</h2>\r\n\r\n<p dir=\"ltr\">Nước tẩy trang Rau M&aacute; chứa c&aacute;c th&agrave;nh phần an to&agrave;n c&oacute; thể sử dụng cho cả những l&agrave;n da nhạy cảm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Purified water (Nước tinh khiết)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Peg 8 Caprylic/ Capric Glycerides</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Propanediol</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Babassu Oil Glycereth-8 Esters</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sorbitol</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Centella Asiatica extract (Chiết xuất Rau m&aacute;</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hyaluronic acid</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Gluconolactone</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Aloe Vera extract (Chiết xuất Nha Đam)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Melaleuca Alternifolia essential oil (Tinh dầu Tr&agrave;m Tr&agrave;)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Curcuma Longa essential oil (Tinh dầu Nghệ).</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em>Tẩy trang l&agrave; một bước l&agrave;m sạch quan trọng v&agrave; cần thiết trong chu tr&igrave;nh chăm s&oacute;c da h&agrave;ng ng&agrave;y. Nếu bạn đang t&igrave;m kiếm một sản phẩm l&agrave;m sạch tốt, d&ugrave;ng được cho da nhạy cảm, h&atilde;y tham khảo ngay&nbsp;<strong>tẩy trang Rau M&aacute;</strong>&nbsp;nh&agrave; Cỏ, bạn nh&eacute;!</em></p>', '171738243420240603094034bBrrDpeBvfvKZ4pRXk0OihvNMMaxtXj7XPgC6w1h.webp', 100.00, 120.00, 3, 120.00, 997, 1, 1, 1, 1, '2024-06-03 02:40:34', '2024-06-09 17:02:59'),
(6, 'Kem Chống Nắng Hây Hây', 'kem-chong-nang-hay-hay-1717382977', 'SP006', 2, 230, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em><strong>Kem chống nắng H&acirc;y H&acirc;y</strong>&nbsp;l&agrave; sản phẩm kem chống nắng của c&ocirc;ng ty cổ phần mỹ phẩm thi&ecirc;n nhi&ecirc;n Cỏ Mềm gi&uacute;p bảo vệ da khỏi t&aacute;c động xấu của c&aacute;c tia cực t&iacute;m, đem đến cho bạn l&agrave;n da mềm mại, khỏe mạnh hơn đồng thời g&oacute;p phần hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a cho da v&agrave; cải thiện t&igrave;nh trạng da dầu mụn.</em></p>\r\n\r\n<p><img alt=\"kem chống nắng hây hây\" src=\"https://static.comem.vn/uploads/2024/04/kem-chong-nang-hay-hay-6_13.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem chống nắng H&acirc;y H&acirc;y</p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Kem chống nắng H&acirc;y H&acirc;y</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dung t&iacute;ch</td>\r\n			<td>60g</td>\r\n		</tr>\r\n		<tr>\r\n			<td>T&iacute;nh chất kem chống nắng</td>\r\n			<td>Vật l&yacute; kết hợp h&oacute;a học</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Loại kem chống nắng</td>\r\n			<td>H&agrave;ng ng&agrave;y/ đi biển</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Kết cấu</td>\r\n			<td>Dạng kem</td>\r\n		</tr>\r\n		<tr>\r\n			<td>M&ugrave;i hương</td>\r\n			<td>Thơm nhẹ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Loại da</td>\r\n			<td>C&oacute; 2 phi&ecirc;n bản d&agrave;nh cho da thường đến kh&ocirc; v&agrave; da dầu mụn</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng. Mở nắp: 12 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật kem chống nắng H&acirc;y H&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Kem chống nắng H&acirc;y H&acirc;y l&agrave; d&ograve;ng sản phẩm chống nắng dạng kem gi&uacute;p bảo vệ da khỏi t&aacute;c hại xấu của c&aacute;c tia UVA, UVB v&agrave; &aacute;nh nắng mặt trời với c&aacute;c đặc điểm nổi bật sau đ&acirc;y:</p>\r\n\r\n<h3 dir=\"ltr\">Bảo vệ da</h3>\r\n\r\n<p dir=\"ltr\">Sản phẩm c&oacute; chỉ số chống nắng SPF 40.25, PA++, thoa l&ecirc;n da h&agrave;ng ng&agrave;y gi&uacute;p bảo vệ da khỏi t&aacute;c hại xấu của tia cực t&iacute;m. Kem chống nắng H&acirc;y H&acirc;y c&oacute; hai phi&ecirc;n bản kem chống nắng cho da dầu mụn v&agrave; kem chống nắng cho da kh&ocirc;, thường</p>\r\n\r\n<p><img alt=\"kem chống nắng hây hây\" src=\"https://static.comem.vn/uploads/2024/04/kem-chong-nang-hay-hay-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem chống nắng H&acirc;y H&acirc;y bảo vệ to&agrave;n diện cho da</p>\r\n\r\n<h3 dir=\"ltr\">Mỏng nhẹ, nhanh thấm</h3>\r\n\r\n<p dir=\"ltr\">Kem chống nắng H&acirc;y H&acirc;y c&oacute; kết cấu kem mỏng nhẹ, thấm nhanh v&agrave;o da, kh&ocirc;ng g&acirc;y nhờn d&iacute;nh v&agrave; kh&ocirc;ng để lại vệt trắng tr&ecirc;n da, kh&ocirc;ng g&acirc;y cảm gi&aacute;c kh&oacute; chịu, duy tr&igrave; sự ẩm mượt, mềm mại cho da.</p>\r\n\r\n<h3 dir=\"ltr\">Gi&uacute;p da s&aacute;ng hơn</h3>\r\n\r\n<p dir=\"ltr\">Sau khi thoa kem chống nắng l&ecirc;n da sẽ tạo một lớp phủ l&ecirc;n bề mặt da, gi&uacute;p l&agrave;n da s&aacute;ng hơn, cho lớp nền mềm mịn.</p>\r\n\r\n<p><img alt=\"kem chống nắng hây hây\" src=\"https://static.comem.vn/uploads/2024/04/kem-chong-nang-hay-hay_39.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem chống nắng H&acirc;y H&acirc;y gi&uacute;p da s&aacute;ng hơn</p>\r\n\r\n<h3 dir=\"ltr\">Tinh dầu Tr&agrave;m tr&agrave; trong phi&ecirc;n bản kem chống nắng H&acirc;y H&acirc;y da dầu gi&uacute;p ngừa mụn</h3>\r\n\r\n<p dir=\"ltr\">Sản phẩm c&oacute; chứa tinh dầu Tr&agrave;m tr&agrave; c&oacute; hoạt t&iacute;nh kh&aacute;ng khuẩn gi&uacute;p ngừa mụn, săn se nốt mụn.&nbsp;</p>\r\n\r\n<h3 dir=\"ltr\">Th&agrave;nh phần an to&agrave;n cho da</h3>\r\n\r\n<p dir=\"ltr\">Kem chống nắng H&acirc;y H&acirc;y c&oacute; chứa c&aacute;c th&agrave;nh phần an to&agrave;n cho da, n&ecirc;n sử dụng h&agrave;ng ng&agrave;y để đạt hiệu quả tốt nhất.</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng kem chống nắng H&acirc;y H&acirc;y</h2>\r\n\r\n<ul>\r\n	<li dir=\"ltr\"><strong>Chống nắng, dưỡng ẩm:&nbsp;</strong>Kem chống nắng H&acirc;y H&acirc;y c&oacute; khả năng dưỡng ẩm cho da, chống nắng, bảo vệ da khỏi t&aacute;c hại xấu của tia UVA, UVB v&agrave; &aacute;nh nắng mặt trời tr&ecirc;n da, đem đến l&agrave;n da mềm mại, khỏe mạnh.</li>\r\n	<li dir=\"ltr\"><strong>Hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a:&nbsp;</strong>Sử dụng kem chống nắng H&acirc;y H&acirc;y gi&uacute;p bảo vệ da h&agrave;ng ng&agrave;y, từ đ&oacute; g&oacute;p phần hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a của da.&nbsp;</li>\r\n</ul>\r\n\r\n<h2 dir=\"ltr\">Ph&acirc;n loại</h2>\r\n\r\n<p dir=\"ltr\">Sản phẩm kem chống nắng H&acirc;y H&acirc;y c&oacute; hai phi&ecirc;n bản cho bạn lựa chọn:</p>\r\n\r\n<h3 dir=\"ltr\">Kem chống nắng H&acirc;y H&acirc;y cho da dầu mụn</h3>\r\n\r\n<p dir=\"ltr\">Đ&acirc;y l&agrave; d&ograve;ng kem chống nắng d&agrave;nh cho da dầu mụn gi&uacute;p chống nắng, dưỡng ẩm cho da, đem đến l&agrave;n da mềm mại đồng thời cải thiện t&igrave;nh trạng da dầu mụn.</p>\r\n\r\n<h3 dir=\"ltr\">Kem chống nắng H&acirc;y H&acirc;y cho da thường, kh&ocirc;</h3>\r\n\r\n<p dir=\"ltr\">Nếu bạn sở hữu l&agrave;n da thường đến kh&ocirc;, đ&acirc;y ch&iacute;nh l&agrave; kem chống nắng cho l&agrave;n da kh&ocirc; của bạn. Sản phẩm bảo vệ da khỏi t&aacute;c hại xấu của tia UV, cho l&agrave;n da khỏe mạnh v&agrave; g&oacute;p phần hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a tr&ecirc;n da.</p>\r\n\r\n<p><img alt=\"kem chống nắng hây hây\" src=\"https://static.comem.vn/uploads/2024/04/kem-chong-nang-hay-hay-4.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem chống nắng H&acirc;y H&acirc;y c&oacute; hai phi&ecirc;n bản d&agrave;nh cho da</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần của sản phẩm</h2>\r\n\r\n<p dir=\"ltr\">Kem chống nắng H&acirc;y H&acirc;y từ mỹ phẩm thi&ecirc;n nhi&ecirc;n Cỏ Mềm chứa c&aacute;c th&agrave;nh phần an to&agrave;n cho l&agrave;n da như:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Nước tinh khiết</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hydrogenated polyisobutene</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Cyclopentasiloxane</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Titanium dioxide</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Aluminium hydroxide</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Stearic acid</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Ethylhexyl methoxycinnamate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Quaternium-18 bentonite</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">DihydroxypropylArginine HCl</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Lauryl peg-9 polydimethylsiloxyethyl dimethicone</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Coco-Caprylate/caprate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Silica</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sorbitan sesquiisostearate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dextrin palmitate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Vitamin E</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sodium chloride</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Phenoxyethanol.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em>Kem chống nắng l&agrave; một bước quan trọng cần thiết trong qu&aacute; tr&igrave;nh chăm s&oacute;c da h&agrave;ng ng&agrave;y. Sản phẩm&nbsp;<strong>kem chống nắng H&acirc;y H&acirc;y</strong>&nbsp;cho da dầu mụn v&agrave; da thường đến kh&ocirc; l&agrave; một lựa chọn hợp l&yacute; cả về chất lượng v&agrave; gi&aacute; th&agrave;nh, n&agrave;ng h&atilde;y nhanh tay cho v&agrave;o giỏ h&agrave;ng để sở hữu sớm nhất nh&eacute;!</em></p>', '171738297720240603094937APAYycstV6Rs85XAqhbOzedLxWBcMmTBn2fl0iKw.webp', 200.00, 260.00, 12, 260.00, 498, 1, 2, 1, 1, '2024-06-03 02:49:37', '2024-06-03 07:18:23'),
(7, 'Xà Bông Hữu Cơ', 'xa-bong-huu-co-1717383223', 'SP007', 4, 19, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em><strong>X&agrave; b&ocirc;ng Hữu cơ</strong>&nbsp;nh&agrave; Cỏ Mềm được nhiều người y&ecirc;u th&iacute;ch bởi đ&acirc;y l&agrave; sản phẩm mang đến l&agrave;n da mềm mịn, kh&ocirc;ng g&acirc;y kh&ocirc; da, kh&ocirc;ng g&acirc;y hại cho sức khỏe cũng như m&ocirc;i trường. X&agrave; b&ocirc;ng Hữu cơ c&ograve;n được biết đến với nhiều c&ocirc;ng dụng như d&ugrave;ng để tắm, rửa mặt, rửa tay tiện lợi.</em></p>\r\n\r\n<p><img alt=\"Xà bông hữu cơ hương Nước hoa có nhiều ưu điểm nổi bật\" src=\"https://static.comem.vn/uploads/March2023/xa-bong-huu-co.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p><em>X&agrave; b&ocirc;ng Hữu cơ Cỏ Mềm</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>X&agrave; b&ocirc;ng Hữu cơ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>H&igrave;nh dạng</td>\r\n			<td>Dạng khối, vỏ giấy c&oacute; in họa tiết, k&egrave;m t&uacute;i lưới tạo bọt</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng</td>\r\n			<td>90 gram</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thể chất</td>\r\n			<td>Dạng khối cứng</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Ph&acirc;n loại</td>\r\n			<td>X&agrave; b&ocirc;ng hữu cơ M&acirc;y, X&agrave; b&ocirc;ng hữu cơ Đ&ecirc;m</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Th&agrave;nh phần</td>\r\n			<td>Ph&ocirc;i x&agrave; ph&ograve;ng hữu cơ (Nước, Glycerin, Sodium Stearate, Sorbitol, Sodium Laurate, Sữa d&ecirc;), Dầu oliu, Fragrance&hellip;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật của x&agrave; b&ocirc;ng Hữu cơ Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">X&agrave; b&ocirc;ng Hữu cơ Cỏ Mềm ghi điểm trong mắt người d&ugrave;ng ngay từ lần sử dụng đầu ti&ecirc;n bởi c&aacute;c ti&ecirc;u ch&iacute;:</p>\r\n\r\n<h3 dir=\"ltr\">4 KH&Ocirc;NG</h3>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Kh&ocirc;ng g&acirc;y kh&ocirc; da</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Kh&ocirc;ng chứa h&oacute;a chất độc hại</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Kh&ocirc;ng hại m&ocirc;i trường</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"Xà bông hữu cơ làm sạch da mà không gây khô da\" src=\"https://static.comem.vn/uploads/March2023/xa-phong-huu-co.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>X&agrave; b&ocirc;ng Hữu cơ Đ&ecirc;m Cỏ Mềm</p>\r\n\r\n<h3 dir=\"ltr\">2 Ph&acirc;n loại</h3>\r\n\r\n<p dir=\"ltr\">X&agrave; b&ocirc;ng Hữu cơ Cỏ Mềm gồm c&oacute; 2 loại x&agrave; b&ocirc;ng cho người d&ugrave;ng lựa chọn với&nbsp; c&aacute;c ưu điểm nổi bật:</p>\r\n\r\n<p dir=\"ltr\"><strong>X&agrave; b&ocirc;ng Hữu cơ M&acirc;y</strong></p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chứa dầu Oliu giữ cho l&agrave;n da mềm mại, kh&ocirc;ng bị kh&ocirc;</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Th&agrave;nh phần đất s&eacute;t hồng c&oacute; t&aacute;c dụng h&uacute;t dầu, l&agrave;m tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, bảo vệ da, kh&aacute;ng khuẩn, chống vi&ecirc;m.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><strong>X&agrave; b&ocirc;ng Hữu cơ Đ&ecirc;m</strong></p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chứa dầu Oliu giữ cho l&agrave;n da mềm mại, kh&ocirc;ng bị kh&ocirc;</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Th&agrave;nh phần bột than tre hoạt t&iacute;nh l&agrave; chất hấp thụ gi&uacute;p loại đi b&atilde; nhờn dư thừa tr&ecirc;n da, gi&uacute;p l&agrave;m th&ocirc;ng tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng của x&agrave; b&ocirc;ng Hữu cơ Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">X&agrave; b&ocirc;ng Hữu cơ nh&agrave; Cỏ l&agrave; sản phẩm x&agrave; b&ocirc;ng c&oacute; nhiều c&ocirc;ng dụng đa dạng như d&ugrave;ng để tắm, rửa mặt, rửa tay, gi&uacute;p l&agrave;m sạch da, kh&aacute;ng khuẩn, giữ cho l&agrave;n da mềm mại, kh&ocirc;ng l&agrave;m kh&ocirc; da.</p>\r\n\r\n<p><img alt=\"Công dụng của xà bông hữu cơ hương Nước hoa lưu hương lâu\" src=\"https://static.comem.vn/uploads/March2023/xa-phong-organic.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>X&agrave; b&ocirc;ng Hữu cơ M&acirc;y Cỏ Mềm</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần của sản phẩm</h2>\r\n\r\n<p dir=\"ltr\">X&agrave; b&ocirc;ng Hữu cơ chứa c&aacute;c th&agrave;nh phần an to&agrave;n kh&ocirc;ng độc hại cho l&agrave;n da, kh&ocirc;ng g&acirc;y hại cho động vật thủy sinh khi thải v&agrave;o nguồn nước v&agrave; kh&ocirc;ng để lại r&aacute;c thải bao b&igrave; chai lọ kh&oacute; ph&acirc;n hủy như:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Ph&ocirc;i x&agrave; b&ocirc;ng hữu cơ: Aqua, Glycerin, Sodium stearate, Sorbitol, Sodium laurate, Goats milk.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu oliu (Olea europaea oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">C&aacute;c th&agrave;nh phần thi&ecirc;n nhi&ecirc;n như: bột than tre hoạt t&iacute;nh (Activated charcoal powder), đất s&eacute;t hồng (Kaolin)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Fragrance.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em>Nếu bạn đang t&igrave;m kiếm một loại x&agrave; b&ocirc;ng tắm vừa gi&uacute;p l&agrave;m sạch da vừa tạo hương thơm dễ chịu lại kh&ocirc;ng g&acirc;y kh&ocirc; da, đừng bỏ qua&nbsp;<strong>x&agrave; b&ocirc;ng Hữu cơ</strong>&nbsp;nh&agrave; Cỏ. Nếu c&ograve;n điều g&igrave; băn khoăn về sản phẩm, h&atilde;y li&ecirc;n hệ với ch&uacute;ng m&igrave;nh ngay nh&eacute;!</em></p>', '171738322320240603095343joko8rvRrPBv0VsU4dnwW2K1lfpSwJL4woMDGtCx.webp', 100.00, 130.00, 9, 130.00, 49, 1, 0, 0, 1, '2024-06-03 02:53:43', '2024-06-03 02:53:43'),
(8, 'Combo Gội Xả Thảo Dược Tóc Mây', 'combo-goi-xa-thao-duoc-toc-may-1717383371', 'SP008', 3, 213, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p><em><strong>Combo gội xả thảo dược T&oacute;c M&acirc;y</strong>&nbsp;nh&agrave; Cỏ l&agrave; combo chăm s&oacute;c t&oacute;c to&agrave;n diện từ b&ecirc;n trong gi&uacute;p m&aacute;i t&oacute;c chắc khỏe, mềm mượt, giảm t&igrave;nh trạng g&atilde;y rụng, chẻ ngọn vốn l&agrave; nỗi lo của nhiều người. Combo l&agrave; sự kết hợp của dầu gội thảo dược T&oacute;c M&acirc;y v&agrave; kem xả ủ T&oacute;c M&acirc;y c&oacute; thể sử dụng cho cả những người c&oacute; da đầu nhạy cảm.</em></p>\r\n\r\n<h2 dir=\"ltr\">Dầu gội thảo dược T&oacute;c M&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Dầu gội thảo dược T&oacute;c M&acirc;y nh&agrave; Cỏ được c&aacute;c chị em tin d&ugrave;ng bởi sản phẩm kh&ocirc;ng chứa h&oacute;a chất độc hại g&acirc;y kh&ocirc;, r&iacute;t da đầu v&agrave; c&oacute; thể sử dụng cho l&agrave;n da nhạy cảm. Được tạo n&ecirc;n từ sự kết hợp với c&aacute;c loại thảo mộc truyền thống v&agrave; hoạt chất thi&ecirc;n nhi&ecirc;n hiện đại gi&uacute;p chăm s&oacute;c m&aacute;i t&oacute;c mềm mượt.</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"bộ gội xả tóc mây\" src=\"https://static.comem.vn/uploads/August2023/bo-goi-xa-toc-may-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p dir=\"ltr\">C&aacute;c th&agrave;nh phần như bồ kết, bồ h&ograve;n v&agrave; cỏ ngũ sắc, hương nhu v&agrave; cỏ mần trầu gi&uacute;p tạo bọt tự nhi&ecirc;n, gi&uacute;p l&agrave;m sạch g&agrave;u. Tinh dầu vỏ bưởi v&agrave; tang bạch b&igrave; c&oacute; t&aacute;c dụng ngăn ngừa rụng t&oacute;c hiệu quả. C&ugrave;ng với tinh dầu sả chanh mang đến hương thơm nhẹ nh&agrave;ng, cảm gi&aacute;c thư gi&atilde;n khi gội đầu, cho bạn những gi&acirc;y ph&uacute;t thoải m&aacute;i sau một ng&agrave;y d&agrave;i. Ngo&agrave;i ra, dầu gội thảo dược T&oacute;c M&acirc;y c&ograve;n chứa c&aacute;c th&agrave;nh phần như dầu quả Bơ, protein đậu H&agrave; Lan l&agrave; nguồn cung cấp dưỡng chất cho t&oacute;c, gi&uacute;p phục hồi m&aacute;i t&oacute;c hư tổn th&ecirc;m chắc khỏe hơn.</p>\r\n\r\n<h2 dir=\"ltr\">Kem xả ủ T&oacute;c M&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Sau khi đ&atilde; l&agrave;m sạch da đầu với dầu gội thảo dược T&oacute;c M&acirc;y, kh&ocirc;ng thể thiếu sản phẩm kem xả ủ T&oacute;c M&acirc;y cho m&aacute;i t&oacute;c b&oacute;ng khỏe, mềm mượt. Kh&ocirc;ng giống như c&aacute;c loại dầu xả h&oacute;a học tr&ecirc;n thị trường với c&aacute;c chất l&agrave;m mượt g&acirc;y b&iacute;t tắc nang t&oacute;c, g&acirc;y nhờn v&agrave; nặng t&oacute;c, kem xả ủ T&oacute;c M&acirc;y l&agrave; b&iacute; quyết cho m&aacute;i t&oacute;c hư tổn, gi&uacute;p t&oacute;c mềm mượt, gi&uacute;p l&agrave;m giảm t&igrave;nh trạng g&atilde;y rụng t&oacute;c, bảo vệ t&oacute;c to&agrave;n diện.</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"bộ gội xả tóc mây\" src=\"https://static.comem.vn/uploads/August2023/bo-goi-xa-toc-may-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p dir=\"ltr\">Kem xả ủ T&oacute;c M&acirc;y l&agrave; sự kết hợp của c&aacute;c th&agrave;nh phần an to&agrave;n cho m&aacute;i t&oacute;c như tinh dầu Vỏ bưởi, tinh dầu Hương nhu, tinh dầu Ngọc lan t&acirc;y, dầu quả Bơ, dầu Oliu, vitamin E, Propanediol chiết xuất từ ng&ocirc; v&agrave; đậu H&agrave; Lan l&agrave; những dưỡng chất cần thiết cho t&oacute;c gi&uacute;p m&aacute;i t&oacute;c su&ocirc;n mượt, b&oacute;ng khỏe m&agrave; kh&ocirc;ng g&acirc;y bết t&oacute;c, g&acirc;y kh&oacute; chịu khi sử dụng.</p>\r\n\r\n<p dir=\"ltr\"><em>Một m&aacute;i t&oacute;c chắc khỏe, mềm mượt ch&iacute;nh l&agrave; &ldquo;vũ kh&iacute;&rdquo; b&iacute; mật của mọi c&ocirc; g&aacute;i gi&uacute;p c&ocirc; ấy tự tin thể hiện c&aacute; t&iacute;nh của m&igrave;nh. Cỏ Mềm hy vọng với&nbsp;<strong>combo gội xả thảo dược T&oacute;c M&acirc;y</strong>, n&agrave;ng sẽ c&oacute; một m&aacute;i t&oacute;c đẹp, bồng bềnh, nhanh tay cho sản phẩm v&agrave;o giỏ h&agrave;ng th&ocirc;i n&agrave;o!</em></p>', '171738337120240603095611Y7qqeMMd8dKaQr8JSRwF4nFpmYYedWoPpeApUY68.webp', 500.00, 540.00, 17, 540.00, 36, 1, 4, 3, 1, '2024-06-03 02:56:11', '2024-06-09 17:31:55');
INSERT INTO `products` (`id`, `name`, `slug`, `code`, `product_category_id`, `manufacturer_id`, `description`, `image`, `price_prime`, `price`, `unit_id`, `price_sale`, `quantity`, `admin_id`, `bought`, `view_count`, `status`, `created_at`, `updated_at`) VALUES
(9, 'Mặt Nạ Ngủ Môi Môi Hồng', 'mat-na-ngu-moi-moi-hong-1717383806', 'SP009', 1, 19, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em><strong>Mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng</strong>&nbsp;l&agrave; sản phẩm c&oacute; c&ocirc;ng dụng gi&uacute;p dưỡng ẩm, l&agrave;m mềm m&ocirc;i, loại bỏ tế b&agrave;o chết tr&ecirc;n m&ocirc;i, từ đ&oacute; ngăn ngừa th&acirc;m m&ocirc;i v&agrave; cải thiện t&igrave;nh trạng m&ocirc;i kh&ocirc; nẻ, bong tr&oacute;c gi&uacute;p đ&ocirc;i m&ocirc;i mềm mại, b&oacute;ng mịn.</em></p>\r\n\r\n<p><img alt=\"mặt nạ ngủ môi hồng\" src=\"https://static.comem.vn/uploads/August2023/mat-na-ngu-moi-moi-hong-5.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng l&agrave; giải ph&aacute;p cho đ&ocirc;i m&ocirc;i kh&ocirc; nẻ</p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Vấn đề của m&ocirc;i</td>\r\n			<td>Kh&ocirc; nẻ, bong tr&oacute;c, kh&ocirc;ng đều m&agrave;u</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dung t&iacute;ch</td>\r\n			<td>8g</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thể chất</td>\r\n			<td>Dạng s&aacute;p mềm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>M&ugrave;i hương</td>\r\n			<td>Dịu nhẹ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng. Mở nắp: 6 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng</h2>\r\n\r\n<p dir=\"ltr\">Mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng nh&agrave; Cỏ l&agrave; sản phẩm mặt nạ ngủ m&ocirc;i được nhiều chị em tin d&ugrave;ng bởi những c&ocirc;ng dụng nổi bật sau đ&acirc;y:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Th&agrave;nh phần c&oacute; chứa Dầu Hạnh Nh&acirc;n, Bơ Hạt Mỡ, Dầu C&aacute;m Gạo an to&agrave;n cho sức khỏe c&oacute; c&ocirc;ng dụng gi&uacute;p dưỡng ẩm, l&agrave;m mềm cho m&ocirc;i.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Hạnh Nh&acirc;n c&oacute; khả năng dưỡng m&ocirc;i, cải thiện t&igrave;nh trạng th&acirc;m m&ocirc;i.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Lanolin c&oacute; chiết xuất từ mỡ cừu gi&uacute;p cải thiện t&igrave;nh trạng kh&ocirc; m&ocirc;i, nứt nẻ tr&ecirc;n m&ocirc;i.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Th&agrave;nh phần Vitamin E gi&uacute;p dưỡng mềm cho m&ocirc;i.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chiết xuất Hoa S&uacute;ng c&oacute; khả năng gi&uacute;p ngăn ngừa h&igrave;nh th&agrave;nh đốm n&acirc;u tr&ecirc;n m&ocirc;i.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\">Với c&aacute;c th&agrave;nh phần an to&agrave;n, l&agrave;nh t&iacute;nh, sản phẩm mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng sử dụng được cho b&agrave; bầu, phụ nữ c&oacute; thai v&agrave; những người c&oacute; đ&ocirc;i m&ocirc;i nhạy cảm.</p>\r\n\r\n<p><img alt=\"mặt nạ ngủ môi môi hồng\" src=\"https://static.comem.vn/uploads/August2023/mat-na-ngu-moi-moi-hong-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Th&agrave;nh phần an to&agrave;n trong mặt nạ m&ocirc;i M&ocirc;i Hồng</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng</h2>\r\n\r\n<p dir=\"ltr\">Mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng c&oacute; c&ocirc;ng dụng hiệu quả trong việc dưỡng ẩm, l&agrave;m mềm da m&ocirc;i, cải thiện t&igrave;nh trạng đ&ocirc;i m&ocirc;i kh&ocirc; nẻ, bong tr&oacute;c, cho bạn một đ&ocirc;i m&ocirc;i mềm mại, b&oacute;ng mịn.</p>\r\n\r\n<p dir=\"ltr\">Ngo&agrave;i ra, sản phẩm c&ograve;n gi&uacute;p loại bỏ tế b&agrave;o chết tr&ecirc;n m&ocirc;i, gi&uacute;p ngăn ngừa th&acirc;m m&ocirc;i. Th&agrave;nh phần từ chiết xuất Hoa S&uacute;ng c&oacute; t&aacute;c dụng hiệu quả gi&uacute;p ngăn ngừa h&igrave;nh th&agrave;nh c&aacute;c đốm n&acirc;u tr&ecirc;n m&ocirc;i.</p>\r\n\r\n<p><img alt=\"mặt nạ ngủ môi môi hồng\" src=\"https://static.comem.vn/uploads/August2023/mat-na-ngu-moi-moi-hong-4.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Mặt nạ ngủ M&ocirc;i Hồng cho đ&ocirc;i m&ocirc;i mềm mại, b&oacute;ng mịn</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng</h2>\r\n\r\n<p dir=\"ltr\">Mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng l&agrave; sản phẩm gi&uacute;p dưỡng m&ocirc;i tốt với c&aacute;c th&agrave;nh phần an to&agrave;n bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Prunus dulcis oil (Dầu Hạnh Nh&acirc;n)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Oryza Sativa Bran Oil (Dầu C&aacute;m Gạo)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Butyrospermum parkii butter (Bơ Hạt Mỡ)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Cocos Nucifera Oil (Dầu Dừa)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dextrin Palmitate, Hydrogenated soybean oil (S&aacute;p Đậu N&agrave;nh)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Lanolin (Chiết xuất mỡ cừu)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Beeswax (S&aacute;p ong)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sodium Palmitoyl Proline (and) Nymphaea Alba Flower Extract (Chiết xuất hoa S&uacute;ng)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tocopherol (Vitamin E).</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em><strong>Mặt nạ ngủ m&ocirc;i M&ocirc;i Hồng</strong>&nbsp;Cỏ Mềm l&agrave; một giải ph&aacute;p d&agrave;nh cho những c&ocirc; n&agrave;ng c&oacute; một l&agrave;n da m&ocirc;i kh&ocirc; r&aacute;p, nứt nẻ, thiếu sức sống. Để đ&ocirc;i m&ocirc;i th&ecirc;m phần mềm mại, b&oacute;ng mịn, h&atilde;y tham khảo ngay sản phẩm mặt nạ ngủ M&ocirc;i hồng n&agrave;y nh&eacute;!</em></p>', '171738380620240603100326eWfQrONArRfHymW2LMcWDatXwyvOcl5Y5YaDGeuP.webp', 100.00, 125.00, 7, 125.00, 694, 1, 5, 3, 1, '2024-06-03 03:03:26', '2024-06-09 17:40:51'),
(10, 'Son Dưỡng Gạo', 'son-duong-gao-1717384539', 'SP0010', 1, 19, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p><em><strong>Son Gạo</strong>&nbsp;Cỏ Mềm l&agrave; d&ograve;ng son dưỡng m&ocirc;i được nhiều chị em tin tưởng sử dụng tr&ecirc;n thị trường hiện nay gi&uacute;p dưỡng cho đ&ocirc;i m&ocirc;i mềm mịn, ngăn ngừa nứt nẻ, giảm th&acirc;m m&ocirc;i hiệu quả.</em></p>\r\n\r\n<p><img alt=\"son gạo\" src=\"https://static.comem.vn/uploads/August2023/son-duong-gao-5.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p><em>Son Gạo Cỏ Mềm gi&uacute;p dưỡng m&ocirc;i mềm mịn</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Son Gạo</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng son</td>\r\n			<td>3,6g</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Ph&acirc;n loại</td>\r\n			<td>Kh&ocirc;ng m&agrave;u/D&acirc;u/Cam</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dạng</td>\r\n			<td>Thỏi</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Th&agrave;nh phần</td>\r\n			<td>Dầu C&aacute;m gạo, dầu Hạnh nh&acirc;n, bơ Hạt mỡ, s&aacute;p Ong, dầu Dừa, dầu Gấc, Vitamin E, m&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n, tinh dầu Cam ngọt, dầu M&ugrave; u&hellip;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>12 th&aacute;ng. Mở nắp: 6 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><img alt=\"son dưỡng gạo\" src=\"https://static.comem.vn/uploads/2024/03/son-gao-co-mem.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Son Gạo an to&agrave;n, l&agrave;nh t&iacute;nh dưỡng m&ocirc;i mềm mịn</p>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật son Gạo Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Son Gạo Cỏ Mềm l&agrave; b&iacute; quyết giữ cho đ&ocirc;i m&ocirc;i mềm mịn với những ưu điểm nổi bật:</p>\r\n\r\n<h3 dir=\"ltr\">Chứa c&aacute;c th&agrave;nh phần an to&agrave;n</h3>\r\n\r\n<p>Sản phẩm&nbsp;<strong><a href=\"https://comem.vn/cm/son-duong-moi\">son dưỡng m&ocirc;i Cỏ Mềm</a></strong>&nbsp;c&oacute; chứa c&aacute;c th&agrave;nh phần như dầu C&aacute;m gạo, dầu quả Bơ, bơ Hạt mỡ, s&aacute;p Ong, dầu Hạnh nh&acirc;n&hellip; c&oacute; c&ocirc;ng dụng hiệu quả trong việc l&agrave;m mềm m&ocirc;i, cung cấp dưỡng chất gi&uacute;p cho đ&ocirc;i m&ocirc;i mềm mịn. Sử dụng son dưỡng Gạo c&ograve;n hỗ trợ giảm th&acirc;m m&ocirc;i v&agrave; an to&agrave;n cho sức khỏe.</p>\r\n\r\n<p><img alt=\"son gạo\" src=\"https://static.comem.vn/uploads/August2023/son-duong-gao-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Son dưỡng Gạo D&acirc;u an to&agrave;n cho sức khỏe</p>\r\n\r\n<h3 dir=\"ltr\">Ba ph&acirc;n loại m&agrave;u</h3>\r\n\r\n<p dir=\"ltr\">Son Gạo Cỏ Mềm c&oacute; ba ph&acirc;n loại ch&iacute;nh bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Son Gạo kh&ocirc;ng m&agrave;u:&nbsp;</strong>l&agrave; d&ograve;ng son dưỡng kh&ocirc;ng m&agrave;u c&oacute; bổ sung dầu gấc gi&uacute;p giảm th&acirc;m m&ocirc;i.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Son Gạo D&acirc;u:&nbsp;</strong>gi&uacute;p l&agrave;m mềm m&ocirc;i, chứa dầu kho&aacute;ng thi&ecirc;n nhi&ecirc;n gi&uacute;p m&ocirc;i l&ecirc;n m&agrave;u phớt hồng tươi tắn.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Son Gạo Cam:</strong>&nbsp;mang hương thơm của tinh dầu Cam ngọt, chứa m&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n gi&uacute;p m&ocirc;i l&ecirc;n m&agrave;u phớt cam tươi tắn.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng son Gạo Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Son Gạo nh&agrave; Cỏ l&agrave; sản phẩm son dưỡng được c&aacute;c chị em y&ecirc;u th&iacute;ch, lựa chọn dưỡng m&ocirc;i h&agrave;ng ng&agrave;y gi&uacute;p dưỡng mềm cho m&ocirc;i. Th&agrave;nh phần tinh dầu M&ugrave; u c&oacute; c&ocirc;ng dụng cải thiện t&igrave;nh trạng nứt nẻ cho m&ocirc;i, giảm th&acirc;m m&ocirc;i.&nbsp;</p>\r\n\r\n<p dir=\"ltr\">Sản phẩm cũng được sử dụng l&agrave;m son l&oacute;t khi trang điểm, đ&aacute;nh một lớp son dưỡng Gạo trước khi đ&aacute;nh son m&agrave;u gi&uacute;p đ&ocirc;i m&ocirc;i l&ecirc;n m&agrave;u chuẩn hơn.</p>\r\n\r\n<p><img alt=\"son gạo\" src=\"https://static.comem.vn/uploads/August2023/son-duong-gao-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Son dưỡng Gạo Cam cải thiện t&igrave;nh trạng nứt nẻ cho m&ocirc;i</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần son Gạo Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Son Gạo Cỏ Mềm c&oacute; chứa c&aacute;c th&agrave;nh phần ch&iacute;nh gi&uacute;p dưỡng m&ocirc;i hiệu quả như:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu C&aacute;m gạo (Oryza sativa bran oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Hạnh nh&acirc;n (Prunus dulcis oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bơ Hạt mỡ (Butyrospermum parkii butter)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">S&aacute;p Ong (Bees wax)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">S&aacute;p Candelilla (Euphorbia cerifera (candelilla) wax)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Dừa (Cocos nucifera oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Gấc (Momordica cochinchinensis oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Vitamin E (Tocopherol)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">M&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Cam ngọt (Citrus sinensis essential oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu M&ugrave; u (Calophyllum inophyllum seed oil).</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em>Dưỡng m&ocirc;i l&agrave; bước quan trọng gi&uacute;p bạn c&oacute; đ&ocirc;i m&ocirc;i mềm mọng, ẩm mượt, gi&uacute;p son l&ecirc;n m&agrave;u đẹp hơn.&nbsp;<strong>Son Gạo</strong>&nbsp;Cỏ Mềm l&agrave; sản phẩm son dưỡng m&ocirc;i hiệu quả, cải thiện t&igrave;nh trạng m&ocirc;i, cho n&agrave;ng một đ&ocirc;i m&ocirc;i mềm mịn.</em></p>', '171738453920240603101539BL2hNCsBjp3QuuH1ZyPNgFLiWsiQJEekXsWXLFVX.webp', 50.00, 90.00, 16, 88.00, 899, 1, 1, 1, 1, '2024-06-03 03:15:39', '2024-06-03 07:44:36'),
(11, 'Kem Nền Hây Hây - Trang Điểm Tối Giản Đẹp Xinh', 'kem-nen-hay-hay-trang-diem-toi-gian-dep-xinh-1717384826', 'SP0011', 2, 294, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em><strong>Kem nền H&acirc;y H&acirc;y</strong>&nbsp;l&agrave; một trong những sản phẩm makeup kh&ocirc;ng thể bỏ qua gi&uacute;p l&agrave;m đều m&agrave;u da, che khuyết điểm, g&oacute;p phần chống nắng cho da, dưỡng da mềm mịn. C&ugrave;ng kh&aacute;m ph&aacute; sản phẩm kem nền n&agrave;y với Cỏ nh&eacute;!</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số nội dung</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Kem nền H&acirc;y H&acirc;y</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thể chất</td>\r\n			<td>Dạng kem lỏng</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Kết cấu kem</td>\r\n			<td>Mỏng nhẹ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Ph&acirc;n loại</td>\r\n			<td>01 Light, 02 Nude</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng</td>\r\n			<td>30g</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Chỉ số SPF</td>\r\n			<td>15.36</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảo quản</td>\r\n			<td>Nơi kh&ocirc; m&aacute;t. Tr&aacute;nh nắng n&oacute;ng v&agrave; nguồn nhiệt</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng. Mở nắp: 12 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật của kem nền H&acirc;y H&acirc;y Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Kem nền H&acirc;y H&acirc;y l&agrave; d&ograve;ng kem trang điểm được nhiều t&iacute;n đồ l&agrave;m đẹp y&ecirc;u th&iacute;ch với c&aacute;c ưu điểm nổi bật phải kể đến như:</p>\r\n\r\n<h3 dir=\"ltr\">Mỏng nhẹ</h3>\r\n\r\n<p dir=\"ltr\">Kết cấu kem mỏng nhẹ, kh&ocirc;ng nhờn d&iacute;nh. Khi thoa kh&ocirc;ng để lại vệt trắng tr&ecirc;n da, nhưng vẫn duy tr&igrave; sự ẩm mượt, mềm mại cho da.</p>\r\n\r\n<p><img alt=\"kem nền hây hây\" src=\"https://static.comem.vn/uploads/August2023/kem-nen-hay-hay-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem nền H&acirc;y H&acirc;y c&oacute; kết cấu mỏng nhẹ, kh&ocirc;ng nhờn d&iacute;nh</p>\r\n\r\n<h3 dir=\"ltr\">Che phủ tốt</h3>\r\n\r\n<p dir=\"ltr\">Sản phẩm kem nền H&acirc;y H&acirc;y gi&uacute;p che phủ tốt khuyết điểm tr&ecirc;n da, gi&uacute;p l&agrave;m đều m&agrave;u da, tạo một lớp phủ bề mặt gi&uacute;p da s&aacute;ng hơn, tạo một lớp nền tự nhi&ecirc;n, tươi s&aacute;ng.</p>\r\n\r\n<h3 dir=\"ltr\">Hỗ trợ chống nắng</h3>\r\n\r\n<p dir=\"ltr\">Kh&ocirc;ng chỉ l&agrave; một sản phẩm gi&uacute;p trang điểm cho da, kem nền H&acirc;y H&acirc;y c&ograve;n hỗ trợ chống nắng cho da với chỉ số SPF 15.36, gi&uacute;p bảo vệ da khỏi tia UV.</p>\r\n\r\n<h3 dir=\"ltr\">Th&agrave;nh phần an to&agrave;n</h3>\r\n\r\n<p dir=\"ltr\">Kem nền H&acirc;y H&acirc;y c&oacute; th&agrave;nh phần an to&agrave;n, l&agrave;nh t&iacute;nh, kh&ocirc;ng g&acirc;y cảm gi&aacute;c bức b&iacute; khi thoa l&ecirc;n da, kh&ocirc;ng g&acirc;y mụn. Sản phẩm đ&atilde; được chứng minh l&agrave; kh&ocirc;ng g&acirc;y k&iacute;ch ứng cho da.</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng kem nền H&acirc;y H&acirc;y nh&agrave; Cỏ</h2>\r\n\r\n<p dir=\"ltr\">Sản phẩm c&oacute; hai tone m&agrave;u l&agrave;<strong>&nbsp;01 Light (s&aacute;ng da)</strong>&nbsp;v&agrave;<strong>&nbsp;02 Nude (tự nhi&ecirc;n)</strong>&nbsp;cho chị em lựa chọn ph&ugrave; hợp với tone da của m&igrave;nh. Kem nền H&acirc;y H&acirc;y được sử dụng gi&uacute;p l&agrave;m đều m&agrave;u da, che khuyết điểm cho da, g&oacute;p phần chống nắng cho da, dưỡng da mềm mịn.</p>\r\n\r\n<p><img alt=\"kem nền hây hây\" src=\"https://static.comem.vn/uploads/August2023/kem-nen-hay-hay.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem nền H&acirc;y H&acirc;y c&oacute; hai tone m&agrave;u lựa chọn</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần kem nền H&acirc;y H&acirc;y nh&agrave; Cỏ</h2>\r\n\r\n<p dir=\"ltr\">Kem nền H&acirc;y H&acirc;y Cỏ Mềm chứa c&aacute;c th&agrave;nh phần an to&agrave;n cho da bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Nước tinh khiết</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Titanium dioxide</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Coco- caprylate/ caprate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Isotridecyl isononanoate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hydrogenated polyisobutene</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Lauryl peg-9 polydimethylsiloxyethyl dimethicone</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Quaternium-18 bentonite</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">M&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dipotassium glycyrrhizinate root extract (Chiết xuất rễ Cam thảo)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sodium chloride v&agrave; Sodium hyaluronate.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><em><strong>Kem nền H&acirc;y H&acirc;y</strong>&nbsp;Cỏ Mềm l&agrave; sản phẩm kem nền gi&uacute;p l&agrave;n da rạng ngời, tươi tắn với hai m&agrave;u ph&ugrave; hợp với từng tone da. H&atilde;y nhanh tay gh&eacute; cửa h&agrave;ng Cỏ Mềm để trải nghiệm sản phẩm trực tiếp hoặc đặt mua h&agrave;ng trực tiếp tr&ecirc;n website để nhanh ch&oacute;ng sở hữu em kem nền n&agrave;y khi trang điểm nh&eacute;!</em></p>', '171738482620240603102026qTTr1ftMqxR1njLKfxwNay6Id7M32RitWBgq3P7H.webp', 150.00, 210.00, 12, 200.00, 199, 1, 1, 1, 1, '2024-06-03 03:20:26', '2024-06-03 03:48:29'),
(12, 'Combo Mụn Lưng - Sạch Mụn Lưng Trong 2 Tuần', 'combo-mun-lung-sach-mun-lung-trong-2-tuan-1717384987', 'SP0012', 4, 304, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em>Mụn lưng l&agrave; t&igrave;nh trạng da nhiều người gặp phải g&acirc;y mất tự tin, cản trở bạn mặc những chiếc v&aacute;y y&ecirc;u th&iacute;ch. Đừng lo nh&eacute;, Cỏ Mềm đ&atilde; c&oacute;&nbsp;<strong>combo trị mụn lưng</strong>&nbsp;cho n&agrave;ng rồi đ&acirc;y. Đ&acirc;y l&agrave; sự kết hợp giữa muối tắm C&agrave; ph&ecirc; Cốt dừa v&agrave; x&agrave; b&ocirc;ng thi&ecirc;n nhi&ecirc;n Tinh than tre an to&agrave;n, l&agrave;nh t&iacute;nh hứa hẹn sẽ l&agrave; combo xua tan đi mụn cơ thể, gi&uacute;p bạn tự tin tỏa s&aacute;ng.&nbsp;</em></p>\r\n\r\n<h2 dir=\"ltr\">Muối tắm C&agrave; ph&ecirc; Cốt dừa</h2>\r\n\r\n<p dir=\"ltr\">Tẩy da chết đều đặn h&agrave;ng tuần cho da gi&uacute;p lấy đi tế b&agrave;o chết tr&ecirc;n da, g&oacute;p phần l&agrave;m sạch lỗ ch&acirc;n l&ocirc;ng, ngừa vi&ecirc;m tắc lỗ ch&acirc;n l&ocirc;ng, đem đến l&agrave;n da s&aacute;ng mịn. Đ&acirc;y ch&iacute;nh l&agrave; bước đầu ti&ecirc;n trong quy tr&igrave;nh trị mụn lưng hiệu quả. Sản phẩm muối tắm C&agrave; ph&ecirc; Cốt dừa nh&agrave; Cỏ c&oacute; th&agrave;nh phần từ c&aacute;c hạt muối biển, bột C&agrave; ph&ecirc; gi&uacute;p l&agrave;m sạch da nhẹ nh&agrave;ng, kết hợp với hương thơm dễ chịu đem đến cảm gi&aacute;c thư gi&atilde;n, sảng kho&aacute;i cho bạn.</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"combo mụn lưng\" src=\"https://static.comem.vn/uploads/August2023/combo-mun-lung-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p dir=\"ltr\">B&ecirc;n cạnh đ&oacute;, với sự kết hợp c&ugrave;ng dầu dừa, dầu Oliu v&agrave; vitamin E dồi d&agrave;o c&oacute; khả năng l&agrave;m mờ vết th&acirc;m, cho l&agrave;n da s&aacute;ng khỏe, mịn m&agrave;ng. Muối tắm C&agrave; ph&ecirc; Cốt dừa c&ograve;n được c&aacute;c chị em y&ecirc;u th&iacute;ch bởi sản phẩm kh&ocirc;ng chứa h&oacute;a chất độc hại c&ugrave;ng khả năng ph&acirc;n hủy tự nhi&ecirc;n n&ecirc;n kh&ocirc;ng g&acirc;y hại cho m&ocirc;i trường.</p>\r\n\r\n<h2 dir=\"ltr\">X&agrave; b&ocirc;ng Thi&ecirc;n nhi&ecirc;n Tinh than tre</h2>\r\n\r\n<p dir=\"ltr\">Thay v&igrave; sử dụng c&aacute;c loại sữa tắm th&ocirc;ng thường c&oacute; chứa hương liệu v&agrave; h&oacute;a chất l&agrave; nguy&ecirc;n nh&acirc;n g&acirc;y b&iacute;t tắc lỗ ch&acirc;n l&ocirc;ng, x&agrave; b&ocirc;ng thi&ecirc;n nhi&ecirc;n Tinh than tre nh&agrave; Cỏ t&iacute;ch hợp ti&ecirc;u ch&iacute; 3 Kh&ocirc;ng (Kh&ocirc;ng chứa h&oacute;a chất độc hại, kh&ocirc;ng g&acirc;y kh&ocirc; da v&agrave; kh&ocirc;ng g&acirc;y hại m&ocirc;i trường).</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"combo mụn lưng\" src=\"https://static.comem.vn/uploads/August2023/combo-mun-lung-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p dir=\"ltr\">Với th&agrave;nh phần từ bột than tre hoạt t&iacute;nh l&agrave; chất hấp thụ c&oacute; t&aacute;c dụng loại bỏ b&atilde; nhờn dư thừa tr&ecirc;n da, l&agrave;m th&ocirc;ng tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, gi&uacute;p trị mụn lưng hiệu quả. Sau khi sử dụng x&agrave; b&ocirc;ng thi&ecirc;n nhi&ecirc;n, bạn kh&ocirc;ng phải lo lắng sản phẩm c&oacute; thể g&acirc;y kh&ocirc; da bởi trong x&agrave; b&ocirc;ng Thi&ecirc;n nhi&ecirc;n Tinh than tre c&oacute; chứa dầu Dừa, dầu Oliu v&agrave; Glycerin gi&uacute;p dưỡng ẩm cho da, kh&ocirc;ng g&acirc;y kh&ocirc; r&iacute;t.&nbsp;</p>\r\n\r\n<p><img alt=\"\" src=\"https://static.comem.vn/uploads/January2022/Quy_trinh_tri_mun_lung_tai_nha.jpg\" style=\"height:612px; width:612px\" /></p>\r\n\r\n<p><em>Đừng để mụn lưng trở th&agrave;nh nỗi &aacute;m ảnh, tự ti của bạn, mụn lưng cũng giống như c&aacute;c t&igrave;nh trạng da kh&aacute;c, đều c&oacute; thể điều trị, quan trọng l&agrave; bạn h&atilde;y ki&ecirc;n tr&igrave; v&agrave; sử dụng sản phẩm ph&ugrave; hợp.&nbsp;<strong>Combo mụn lưng</strong>&nbsp;nh&agrave; Cỏ ch&iacute;nh l&agrave; một gợi &yacute; bạn kh&ocirc;ng n&ecirc;n bỏ qua để c&oacute; một l&agrave;n da mịn m&agrave;ng, tự tin.</em></p>\r\n\r\n<p>---------------------</p>', '171738498720240603102307SpjoONrP8DKxXi41wXLfyA8jqfLtN2UmAcvvohbu.webp', 200.00, 300.00, 17, 300.00, 298, 1, 2, 2, 1, '2024-06-03 03:23:07', '2024-06-09 17:20:54'),
(13, 'Combo Chăm Sóc Da BAN NGÀY', 'combo-cham-soc-da-ban-ngay-1717385653', 'SP0013', 2, 22, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em>Sử dụng Sữa rửa mặt, toner, kem dưỡng ẩm, kem chống nắng l&agrave; c&aacute;c bước thiết yếu trước khi ra khỏi nh&agrave; của mỗi c&ocirc; g&aacute;i. Bộ chăm s&oacute;c da chiết xuất Tơ Tằm gi&uacute;p chăm s&oacute;c l&agrave;n da khỏe mạnh từ b&ecirc;n trong, kết hợp c&ugrave;ng với kem chống nắng H&acirc;y H&acirc;y bảo vệ l&agrave;n da khỏi t&aacute;c động của tia UV. C&ugrave;ng kh&aacute;m ph&aacute;&nbsp;<strong>combo chăm s&oacute;c da BAN NG&Agrave;Y</strong>&nbsp;nh&agrave; Cỏ c&oacute; g&igrave; đặc biệt nh&eacute;!</em></p>\r\n\r\n<h2 dir=\"ltr\">Bước 1: Sữa rửa mặt tạo bọt Tơ Tằm</h2>\r\n\r\n<p dir=\"ltr\">Sữa rửa mặt tạo bọt Tơ Tằm l&agrave; sản phẩm gi&uacute;p l&agrave;m sạch da với độ pH 5.5 ph&ugrave; hợp với mọi loại da, kể cả l&agrave;n da nhạy cảm. Sản phẩm được sử dụng gi&uacute;p l&agrave;m sạch da, duy tr&igrave; độ ẩm tự nhi&ecirc;n cho l&agrave;n da, l&agrave;m sạch tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, cho bạn l&agrave;n da mịn m&agrave;ng.&nbsp;</p>\r\n\r\n<p dir=\"ltr\">Sữa rửa mặt tạo bọt Tơ Tằm l&agrave; sự kết hợp của c&aacute;c th&agrave;nh phần l&agrave;m sạch c&oacute; nguồn gốc từ thi&ecirc;n nhi&ecirc;n, Glycerin, chiết xuất Tơ Tằm v&agrave; Hyaluronic acid c&oacute; c&ocirc;ng dụng gi&uacute;p dưỡng ẩm, giảm kh&ocirc; sần da, cho bạn l&agrave;n da mềm mại. Vitamin B5 l&agrave; hoạt chất gi&uacute;p hạn chế sự mất nước qua lớp biểu b&igrave; của da. V&agrave; kh&ocirc;ng thể thiếu Betaine l&agrave; chất giữ ẩm tự nhi&ecirc;n tr&ecirc;n da l&agrave;m dịu da, giảm khả năng k&iacute;ch ứng v&agrave; duy tr&igrave; h&agrave;ng r&agrave;o bảo vệ da.</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"combo chăm sóc da ban ngày\" src=\"https://static.comem.vn/uploads/August2023/combo-cham-soc-da-ban-ngay-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<h2 dir=\"ltr\">Bước 2: Active Toner Tơ Tằm</h2>\r\n\r\n<p dir=\"ltr\">Sử dụng Active Toner Tơ Tằm trong chu tr&igrave;nh chăm s&oacute;c da ban ng&agrave;y gi&uacute;p c&acirc;n bằng độ pH cho l&agrave;n da, duy tr&igrave; độ ẩm tự nhi&ecirc;n. Active Toner Tơ Tằm nh&agrave; Cỏ c&ograve;n giảm kh&ocirc; sần da, g&oacute;p phần thu nhỏ lỗ ch&acirc;n l&ocirc;ng, cho bạn một l&agrave;n da căng mịn.&nbsp;</p>\r\n\r\n<p dir=\"ltr\">Với chiết xuất từ Tơ Tằm, l&aacute; Nha Đam v&agrave; Propanediol gi&uacute;p dưỡng ẩm, tăng khả năng gi&uacute;p da hấp thu c&aacute;c dưỡng chất ph&iacute;a sau. B&ecirc;n cạnh đ&oacute; l&agrave; sự kết hợp của c&aacute;c th&agrave;nh phần như Vitamin B5, Betaine v&agrave; Niacinamide 2% gi&uacute;p cải thiện đ&aacute;ng kể b&atilde; nhờn dư thừa tr&ecirc;n da, duy tr&igrave; độ mềm mại, đ&agrave;n hồi cho da.</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"combo chăm sóc da ban ngày\" src=\"https://static.comem.vn/uploads/August2023/combo-cham-soc-da-ban-ngay-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<h2 dir=\"ltr\">Bước 3: Kem dưỡng ẩm Tơ Tằm</h2>\r\n\r\n<p dir=\"ltr\">Nếu bạn đang t&igrave;m kiếm một sản phẩm dưỡng ẩm an to&agrave;n, hiệu quả cho da, kem dưỡng ẩm Tơ Tằm ch&iacute;nh l&agrave; lựa chọn h&agrave;ng đầu. Kh&ocirc;ng chỉ cần cấp ẩm v&agrave;o ban đ&ecirc;m, khi chăm s&oacute;c da ban ng&agrave;y, dưỡng ẩm l&agrave; bước kh&ocirc;ng thể thiếu. Kem dưỡng ẩm Tơ Tằm nh&agrave; Cỏ chứa chiết xuất Tơ Tằm thủy ph&acirc;n, Hyaluronic acid v&agrave; Propanediol gi&uacute;p l&agrave;n da mềm mại, mịn m&agrave;ng.&nbsp;</p>\r\n\r\n<p dir=\"ltr\">Kh&ocirc;ng chỉ vậy, kem dưỡng ẩm Tơ Tằm với sự kết hợp của Ubiquinone v&agrave; protein sữa ong ch&uacute;a gi&uacute;p ngăn ngừa l&atilde;o h&oacute;a, hạn chế nếp nhăn tr&ecirc;n da, bảo vệ l&agrave;n da khỏi &aacute;nh s&aacute;ng của tia UV, duy tr&igrave; một l&agrave;n da căng mịn.</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"combo chăm sóc da ban ngày\" src=\"https://static.comem.vn/uploads/August2023/combo-cham-soc-da-ban-ngay-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<h2 dir=\"ltr\">Bước 4: Kem chống nắng H&acirc;y H&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Sử dụng kem chống nắng l&agrave; bước v&ocirc; c&ugrave;ng cần thiết để bảo vệ da khỏi t&aacute;c động xấu của tia UV. Kem chống nắng H&acirc;y H&acirc;y nh&agrave; Cỏ với kết cấu mỏng nhẹ, nhanh thấm v&agrave;o da n&ecirc;n khi thoa kh&ocirc;ng g&acirc;y nhờn d&iacute;nh v&agrave; cảm gi&aacute;c kh&oacute; chịu, b&iacute; b&aacute;ch tr&ecirc;n da. Sản phẩm c&oacute; chỉ số chống nắng SPF 40.25, PA++ gi&uacute;p bảo vệ da khỏi t&aacute;c hại của tia UV, tạo một lớp phủ l&ecirc;n bề mặt da, cho l&agrave;n da s&aacute;ng khỏe, tạo một lớp nền mềm mịn tr&ecirc;n da, hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a tr&ecirc;n da.</p>\r\n\r\n<p dir=\"ltr\">Sản phẩm c&oacute; hai ph&acirc;n loại bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Kem chống nắng H&acirc;y H&acirc;y cho da dầu mụn</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Kem chống nắng H&acirc;y H&acirc;y cho da thường, kh&ocirc;</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"combo chăm sóc da ban ngày\" src=\"https://static.comem.vn/uploads/August2023/combo-cham-soc-da-ban-ngay-4.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p dir=\"ltr\"><em>Tr&ecirc;n đ&acirc;y l&agrave;&nbsp;<strong>combo chăm s&oacute;c da ban ng&agrave;y</strong>&nbsp;với 4 bước cơ bản nhất vừa gi&uacute;p dưỡng da vừa bảo vệ l&agrave;n da khỏe mạnh. Nếu bạn c&ograve;n băn khoăn g&igrave; về sản phẩm, h&atilde;y li&ecirc;n hệ ngay với ch&uacute;ng m&igrave;nh nh&eacute;!</em></p>', '171738565320240603103413howFHRUJBMF3i9TEipUB7DIRq8p0TCbP57tQQKjG.webp', 800.00, 859.00, 17, 850.00, 93, 1, 6, 3, 1, '2024-06-03 03:34:13', '2024-06-09 17:38:36'),
(14, 'Combo Son Kem Nhung + Son Dưỡng', 'combo-son-kem-nhung-son-duong-1717398419', 'SP020', 1, 294, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><strong>Combo Son Kem Nhung + Son dưỡng</strong>&nbsp;Cỏ Mềm được nhiều chị em tin tưởng sử dụng bởi đ&acirc;y l&agrave; combo gi&uacute;p n&agrave;ng c&oacute; đ&ocirc;i m&ocirc;i mềm mịn, rạng ngời tự nhi&ecirc;n, tự tin tỏa s&aacute;ng.&nbsp;</p>\r\n\r\n<h2 dir=\"ltr\">Son Kem Nhung</h2>\r\n\r\n<p dir=\"ltr\">Nếu n&agrave;ng đang t&igrave;m kiếm một d&ograve;ng son an to&agrave;n cho m&ocirc;i, son Kem Nhung ch&iacute;nh l&agrave; c&acirc;u trả lời. Đ&acirc;y l&agrave; d&ograve;ng son với th&agrave;nh phần thi&ecirc;n nhi&ecirc;n l&agrave; b&iacute; quyết trang điểm v&agrave; che khuyết điểm cho m&ocirc;i, gi&uacute;p dưỡng m&ocirc;i mềm mịn, ngăn ngừa nứt nẻ v&agrave; cải thiện t&igrave;nh trạng th&acirc;m m&ocirc;i.&nbsp;</p>\r\n\r\n<p dir=\"ltr\">Son Kem Nhung l&agrave; d&ograve;ng son kh&ocirc;ng chứa silicon, c&oacute; m&agrave;u kho&aacute;ng đạt ti&ecirc;u chuẩn FDA của Hoa Kỳ c&oacute; t&aacute;c dụng giữ m&agrave;u son tr&ecirc;n m&ocirc;i l&acirc;u hơn. Bảng m&agrave;u đa dạng của son kem Nhung với 5 m&atilde; m&agrave;u chắc chắn sẽ kh&ocirc;ng khiến n&agrave;ng thất vọng:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>M&agrave;u 31:</strong>&nbsp;Đỏ thuần</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>M&agrave;u 32:</strong>&nbsp;Đỏ n&acirc;u</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>M&agrave;u 33:</strong>&nbsp;Đỏ cam</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>M&agrave;u 34:</strong>&nbsp;Cam san h&ocirc;</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>M&agrave;u 35:</strong>&nbsp;Đỏ lạnh</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"combo son kem nhung son dưỡng\" src=\"https://static.comem.vn/uploads/August2023/combo-son-kem-nhung-son-duong-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<h2 dir=\"ltr\">Son dưỡng</h2>\r\n\r\n<p dir=\"ltr\">Son dưỡng nh&agrave; Cỏ gồm c&oacute; son Gạo, son T&aacute;o v&agrave; son dưỡng M&ocirc;i Hồng được nhiều chị em tin tưởng sử dụng, l&agrave; b&iacute; quyết dưỡng cho đ&ocirc;i m&ocirc;i mềm mịn, ngăn ngừa nứt nẻ, giảm th&acirc;m m&ocirc;i:</p>\r\n\r\n<h3 dir=\"ltr\">Son Gạo</h3>\r\n\r\n<p dir=\"ltr\">Son Gạo Cỏ Mềm được tạo n&ecirc;n từ c&aacute;c th&agrave;nh phần như dầu C&aacute;m gạo, dầu quả Bơ, bơ Hạt Mỡ, dầu Hạnh nh&acirc;n gi&uacute;p l&agrave;m mềm m&ocirc;i, cung cấp c&aacute;c dưỡng chất cho n&agrave;ng đ&ocirc;i m&ocirc;i mềm mịn. Sử dụng son Gạo n&agrave;ng c&oacute; thể an t&acirc;m bởi sản phẩm an to&agrave;n cho sức khỏe với ba ph&acirc;n loại ch&iacute;nh bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Son Gạo kh&ocirc;ng m&agrave;u:</strong>&nbsp;d&ograve;ng son dưỡng kh&ocirc;ng m&agrave;u c&oacute; bổ sung dầu gấc gi&uacute;p giảm th&acirc;m m&ocirc;i.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Son Gạo D&acirc;u:</strong>&nbsp;gi&uacute;p l&agrave;m mềm m&ocirc;i, chứa dầu kho&aacute;ng thi&ecirc;n nhi&ecirc;n gi&uacute;p m&ocirc;i l&ecirc;n m&agrave;u phớt hồng tươi tắn.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Son Gạo Cam:</strong>&nbsp;mang hương thơm của tinh dầu Cam ngọt, chứa m&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n gi&uacute;p m&ocirc;i l&ecirc;n m&agrave;u phớt cam.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"combo son kem nhung son dưỡng\" src=\"https://static.comem.vn/uploads/August2023/combo-son-kem-nhung-son-duong-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<h3 dir=\"ltr\">Son T&aacute;o</h3>\r\n\r\n<p dir=\"ltr\">L&agrave; d&ograve;ng son dưỡng với chiết xuất từ dầu hạt T&aacute;o, dầu Hạnh nh&acirc;n, dầu C&aacute;m gạo, kh&ocirc;ng chứa c&aacute;c th&agrave;nh phần c&oacute; nguồn gốc từ động vật, son T&aacute;o Cỏ Mềm c&oacute; c&ocirc;ng dụng dưỡng m&ocirc;i mềm mịn, ngăn ngừa nứt nẻ hiệu quả cho m&ocirc;i.</p>\r\n\r\n<p dir=\"ltr\">Sản phẩm son T&aacute;o Cỏ Mềm c&oacute; hai ph&acirc;n loại m&agrave;u bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Son T&aacute;o Xanh:</strong>&nbsp;son dưỡng kh&ocirc;ng m&agrave;u</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Son T&aacute;o Đỏ:</strong>&nbsp;son dưỡng c&oacute; m&agrave;u chứa m&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n l&ecirc;n m&ocirc;i phớt đỏ.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"combo son kem nhung son dưỡng\" src=\"https://static.comem.vn/uploads/August2023/combo-son-kem-nhung-son-duong-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<h3 dir=\"ltr\">Son dưỡng M&ocirc;i Hồng</h3>\r\n\r\n<p dir=\"ltr\">Son dưỡng M&ocirc;i Hồng được nhiều t&iacute;n đồ l&agrave;m đẹp y&ecirc;u th&iacute;ch bởi c&ocirc;ng dụng dưỡng ẩm hiệu quả cho đ&ocirc;i m&ocirc;i, th&agrave;nh phần l&agrave;nh t&iacute;nh n&ecirc;n an to&agrave;n cho cả b&agrave; bầu. Kh&ocirc;ng chỉ dưỡng mềm m&ocirc;i, son dưỡng M&ocirc;i Hồng c&ograve;n hỗ trợ ngăn ngừa nếp nhăn tr&ecirc;n m&ocirc;i, giảm th&acirc;m m&ocirc;i, cho bạn đ&ocirc;i m&ocirc;i hồng h&agrave;o.</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"combo son kem nhung son dưỡng\" src=\"https://static.comem.vn/uploads/August2023/combo-son-kem-nhung-son-duong-4.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p dir=\"ltr\"><em><strong>Combo Son Kem Nhung + Son dưỡng</strong>&nbsp;l&agrave; combo d&agrave;nh cho c&aacute;c c&ocirc; g&aacute;i nh&agrave; Cỏ chăm s&oacute;c đ&ocirc;i m&ocirc;i to&agrave;n diện v&agrave; tự tin diện những m&agrave;u son đẹp nhất. Nếu n&agrave;ng c&ograve;n điều g&igrave; băn khoăn, h&atilde;y li&ecirc;n hệ ngay với Cỏ để được giải đ&aacute;p chi tiết nh&eacute;!</em></p>', '171739841920240603140659IIrNl4Q7tTbmUDW03YhNS9bJDd9C1tQ5fLggnkqL.webp', 200.00, 250.00, 16, 230.00, 9, 1, 1, 1, 1, '2024-06-03 07:06:59', '2024-06-09 03:46:53'),
(15, 'Bộ Chăm Sóc Da Sâm 1700 3 Bước', 'bo-cham-soc-da-sam-1700-3-buoc-1717398544', 'SP021', 2, 224, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em><strong>Bộ chăm s&oacute;c da chiết xuất S&acirc;m 1700 3 bước</strong>&nbsp;nh&agrave; Cỏ Mềm vừa gi&uacute;p l&agrave;m sạch, vừa gi&uacute;p dưỡng da hiệu quả với c&aacute;c bước kh&ocirc;ng thể thiếu, cho n&agrave;ng một l&agrave;n da sạch khỏe.</em></p>\r\n\r\n<h2 dir=\"ltr\">Nước tẩy trang S&acirc;m 1700</h2>\r\n\r\n<p dir=\"ltr\">Nước tẩy trang S&acirc;m 1700 l&agrave; sản phẩm tẩy trang được c&aacute;c t&iacute;n đồ l&agrave;m đẹp tin d&ugrave;ng nhờ c&ocirc;ng dụng hiệu quả trong việc l&agrave;m sạch da, loại bỏ lớp trang điểm, bụi bẩn v&agrave; dầu thừa tr&ecirc;n da, g&oacute;p phần l&agrave;m tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, gi&uacute;p c&aacute;c bước dưỡng da tiếp theo đạt hiệu quả tốt.</p>\r\n\r\n<p dir=\"ltr\">B&ecirc;n cạnh đ&oacute;, sản phẩm c&ograve;n gi&uacute;p duy tr&igrave; độ ẩm tự nhi&ecirc;n, cho l&agrave;n da mềm mại, s&aacute;ng khỏe. Nước tẩy trang S&acirc;m 1700 nh&agrave; Cỏ c&oacute; thể sử dụng được cho cả v&ugrave;ng mắt v&agrave; m&ocirc;i.</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"bộ chăm sóc da sâm 1700 3 bước\" src=\"https://static.comem.vn/uploads/July2023/bo-cham-soc-da-sam-1700-combo-3-buoc-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<h2 dir=\"ltr\">Sữa rửa mặt S&acirc;m 1700</h2>\r\n\r\n<p dir=\"ltr\">Sữa rửa mặt S&acirc;m 1700 được y&ecirc;u th&iacute;ch bởi hiệu quả l&agrave;m sạch da, l&agrave;m th&ocirc;ng tho&aacute;ng lỗ ch&acirc;n l&ocirc;ng, duy tr&igrave; độ ẩm tự nhi&ecirc;n cho da. L&agrave; một trong những d&ograve;ng sữa rửa mặt nh&agrave; Cỏ đầu ti&ecirc;n chứa chiết xuất S&acirc;m Lai Ch&acirc;u c&ograve;n hỗ trợ gi&uacute;p l&agrave;n da s&aacute;ng sạch, khỏe mạnh.</p>\r\n\r\n<p dir=\"ltr\"><img alt=\"bộ chăm sóc da sâm 1700 3 bước\" src=\"https://static.comem.vn/uploads/July2023/bo-cham-soc-da-sam-1700-combo-3-buoc-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<h2 dir=\"ltr\">Toner S&acirc;m 1700 ngừa l&atilde;o h&oacute;a da&nbsp;</h2>\r\n\r\n<p dir=\"ltr\">Toner S&acirc;m 1700 ngừa l&atilde;o h&oacute;a l&agrave; sản phẩm chăm s&oacute;c da gi&uacute;p:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Cấp ẩm, bổ sung dưỡng chất cho da:</strong>&nbsp;Sau khi rửa mặt, da c&oacute; thể mất đi độ ẩm tự nhi&ecirc;n, toner S&acirc;m 1700 gi&uacute;p cấp ẩm v&agrave; bổ sung dưỡng chất cho da, duy tr&igrave; độ pH tự nhi&ecirc;n, cải thiện t&igrave;nh trạng da kh&ocirc; sần, l&agrave;m mềm mịn da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Thu mờ lỗ ch&acirc;n l&ocirc;ng:</strong>&nbsp;Lỗ ch&acirc;n l&ocirc;ng to lu&ocirc;n khiến ch&uacute;ng ta đau đầu v&agrave; mất tự tin. Sử dụng toner S&acirc;m 1700 gi&uacute;p l&agrave;m mờ lỗ ch&acirc;n l&ocirc;ng, cho l&agrave;n da s&aacute;ng khỏe.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Ngăn ngừa l&atilde;o h&oacute;a da:</strong>&nbsp;Toner ngừa l&atilde;o h&oacute;a S&acirc;m 1700 c&oacute; chiết xuất từ s&acirc;m Lai Ch&acirc;u c&oacute; t&aacute;c dụng l&agrave;m s&aacute;ng da, hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a da sớm.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h2 dir=\"ltr\">Serum S&acirc;m 1700 ngừa l&atilde;o ho&aacute; da</h2>\r\n\r\n<p dir=\"ltr\">Serum ngừa l&atilde;o h&oacute;a S&acirc;m 1700 được nhiều người lựa chọn sử dụng trong chu tr&igrave;nh dưỡng da h&agrave;ng ng&agrave;y với c&ocirc;ng dụng:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Dưỡng ẩm:</strong>&nbsp;Serum S&acirc;m 1700 chứa c&aacute;c th&agrave;nh phần cấp ẩm cho da, cung cấp dưỡng chất gi&uacute;p l&agrave;n da căng mịn.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a da:</strong>&nbsp;Từ độ tuổi 25 trở đi, da bắt đầu xuất hiện t&igrave;nh trạng l&atilde;o h&oacute;a. Serum dưỡng da ngừa l&atilde;o h&oacute;a nh&agrave; Cỏ c&oacute; chứa chiết xuất từ s&acirc;m Lai Ch&acirc;u gi&uacute;p l&agrave;m mờ c&aacute;c đốm n&acirc;u, nếp nhăn tr&ecirc;n da, g&oacute;p phần hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a da sớm.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"bộ chăm sóc da sâm 1700 3 bước\" src=\"https://static.comem.vn/uploads/July2023/bo-cham-soc-da-sam-1700-combo-3-buoc-4.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<h2 dir=\"ltr\">Kem dưỡng ẩm S&acirc;m 1700 ngừa l&atilde;o ho&aacute; da</h2>\r\n\r\n<p dir=\"ltr\">Kem dưỡng ẩm ngừa l&atilde;o h&oacute;a S&acirc;m 1700 của nh&agrave; Cỏ l&agrave; sản phẩm được sử dụng trong chu tr&igrave;nh chăm s&oacute;c da h&agrave;ng ng&agrave;y của c&aacute;c n&agrave;ng với c&ocirc;ng dụng:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Dưỡng ẩm da:</strong>&nbsp;Sản phẩm cung cấp dưỡng chất gi&uacute;p dưỡng ẩm cho da. Với c&aacute;c th&agrave;nh phần như Vitamin B5, Hyaluronic acid&hellip; gi&uacute;p giữ ẩm, giảm t&igrave;nh trạng kh&ocirc; sần tr&ecirc;n da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>L&agrave;n da căng mịn, s&aacute;ng khỏe:</strong>&nbsp;Kem dưỡng ẩm S&acirc;m 1700 c&oacute; khả năng l&agrave;m mờ c&aacute;c đốm n&acirc;u tr&ecirc;n da, cải thiện c&aacute;c nếp nhăn, cho l&agrave;n da căng mịn, s&aacute;ng khỏe.&nbsp;</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a da sớm:</strong>&nbsp;Với chiết xuất từ S&acirc;m Lai Ch&acirc;u Việt Nam, kem dưỡng ẩm S&acirc;m 1700 ph&aacute;t huy c&ocirc;ng dụng trong việc hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a tr&ecirc;n da.&nbsp;</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"bộ chăm sóc da sâm 1700 3 bước\" src=\"https://static.comem.vn/uploads/July2023/bo-cham-soc-da-sam-1700-combo-3-buoc-5.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p dir=\"ltr\"><em><strong>Bộ chăm s&oacute;c da S&acirc;m 1700 3 bước</strong>&nbsp;l&agrave; bộ chăm s&oacute;c da cần thiết cho c&aacute;c c&ocirc; g&aacute;i nh&agrave; Cỏ, cho n&agrave;ng một l&agrave;n da s&aacute;ng sạch, hạn chế qu&aacute; tr&igrave;nh l&atilde;o h&oacute;a tr&ecirc;n da. H&atilde;y cho ngay sản phẩm v&agrave;o giỏ h&agrave;ng th&ocirc;i, bạn ơi!</em></p>', '171739854420240603140904oFYj1FjKWSMSWkWDfbYrjMhpBq0yiRbidN4z5PqB.webp', 1000.00, 1270.00, 17, 1200.00, 4, 1, 1, 1, 1, '2024-06-03 07:09:04', '2024-06-03 07:15:35'),
(16, 'Hair Serum Tóc Mây', 'hair-serum-toc-may-1717398830', 'SP022', 3, 304, '<p><em><strong>Hair serum T&oacute;c M&acirc;y</strong>&nbsp;l&agrave; sản phẩm nằm trong bộ chăm s&oacute;c t&oacute;c nh&agrave; Cỏ gi&uacute;p dưỡng t&oacute;c su&ocirc;n mượt, giảm t&igrave;nh trạng t&oacute;c xơ rối, g&atilde;y rụng, bảo vệ t&oacute;c khỏi h&oacute;a chất, nhiệt độ, bụi bẩn từ m&ocirc;i trường b&ecirc;n ngo&agrave;i&hellip; Đ&acirc;y l&agrave; b&iacute; quyết cho m&aacute;i t&oacute;c mềm mượt, chắc khỏe.</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Hair serum T&oacute;c M&acirc;y</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng</td>\r\n			<td>50ml</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dạng sản phẩm</td>\r\n			<td>Kết cấu serum dạng lỏng</td>\r\n		</tr>\r\n		<tr>\r\n			<td>M&ugrave;i hương</td>\r\n			<td>Hương thơm dịu nhẹ từ c&aacute;c tinh chất từ thi&ecirc;n nhi&ecirc;n</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Vấn đề của t&oacute;c</td>\r\n			<td>T&oacute;c kh&ocirc; v&agrave; xơ rối, chẻ ngọn, đứt g&atilde;y, m&aacute;i t&oacute;c yếu,...</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Đối tượng sử dụng</td>\r\n			<td>D&agrave;nh cho người t&oacute;c thường, t&oacute;c kh&ocirc;, t&oacute;c dầu, t&oacute;c hỗn hợp kh&ocirc; - dầu, t&oacute;c đ&atilde; qua xử l&yacute; h&oacute;a chất như uốn, &eacute;p, tẩy, nhuộm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thời điểm sử dụng</td>\r\n			<td>D&ugrave;ng tốt nhất sau khi gội đầu v&agrave; trước khi sấy t&oacute;c</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật của hair serum T&oacute;c M&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Hair serum T&oacute;c M&acirc;y l&agrave; giải ph&aacute;p cho m&aacute;i t&oacute;c hư tổn, xơ rối với c&ocirc;ng thức kết hợp c&aacute;c thảo mộc truyền thống v&agrave; hoạt chất thi&ecirc;n nhi&ecirc;n hiện đại. Sản phẩm c&oacute; dạng nhỏ giọt d&ugrave;ng để massage v&agrave;o ch&acirc;n t&oacute;c sau khi gội đầu, tận dụng sức n&oacute;ng v&agrave; sự mềm mại của đầu ng&oacute;n tay gi&uacute;p dưỡng chất ngấm s&acirc;u v&agrave;o ch&acirc;n t&oacute;c v&agrave; ph&aacute;t huy t&aacute;c dụng.</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Tinh dầu Vỏ bưởi:</strong>&nbsp;G&oacute;p phần ngăn ngừa rụng t&oacute;c</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Tinh dầu Hương nhu:</strong>&nbsp;Ngăn ngừa rụng t&oacute;c, thư gi&atilde;n khi gội đầu</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Keratin thủy ph&acirc;n chiết xuất từ l&ocirc;ng cừu:</strong>&nbsp;Bảo vệ t&oacute;c khỏi t&aacute;c động của nhiệt độ, h&oacute;a chất v&agrave; m&ocirc;i trường</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Chiết xuất Bạch quả l&ecirc;n men:</strong>&nbsp;Tăng cường dưỡng chất nu&ocirc;i dưỡng t&oacute;c</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Chiết xuất quả M&acirc;m x&ocirc;i:</strong>&nbsp;Ngăn ngừa rụng t&oacute;c</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>DihydroxypropylArginine:</strong>&nbsp;C&oacute; t&aacute;c dụng phục hồi t&oacute;c hư tổn, đặc biệt l&agrave; với t&oacute;c bị ảnh hưởng nhiều bởi h&oacute;a chất, t&oacute;c bị tẩy. Ngo&agrave;i ra, Arginine c&ograve;n c&oacute; t&aacute;c dụng dưỡng ẩm cho da đầu</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Tinh dầu hoắc hương:</strong>&nbsp;C&oacute; khả năng kh&aacute;ng khuẩn.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"hair serum tóc mây\" src=\"https://static.comem.vn/uploads/August2023/hair-serum-toc-may-5.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Hair serum T&oacute;c M&acirc;y l&agrave; giải ph&aacute;p cho m&aacute;i t&oacute;c hư tổn</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng của hair serum T&oacute;c M&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Hair serum T&oacute;c M&acirc;y l&agrave; sản phẩm serum dưỡng t&oacute;c su&ocirc;n mượt. Sản phẩm gi&uacute;p cung cấp dưỡng chất gi&uacute;p ngăn ngừa v&agrave; l&agrave;m giảm t&igrave;nh trạng t&oacute;c xơ rối, g&atilde;y rụng. Sản phẩm c&ograve;n gi&uacute;p bảo vệ t&oacute;c khỏi t&aacute;c hại của h&oacute;a chất, nhiệt độ, bụi bẩn từ m&ocirc;i trường b&ecirc;n ngo&agrave;i&hellip; cho bạn m&aacute;i t&oacute;c mềm mượt, chắc khỏe. Sử dụng hair serum T&oacute;c M&acirc;y g&oacute;p phần k&iacute;ch th&iacute;ch sự ph&aacute;t triển của nang t&oacute;c.</p>\r\n\r\n<p><img alt=\"hair serum tóc mây\" src=\"https://static.comem.vn/uploads/August2023/hair-serum-toc-may-4.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Sản phẩm gi&uacute;p k&iacute;ch th&iacute;ch sự ph&aacute;t triển của nang t&oacute;c</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần của sản phẩm</h2>\r\n\r\n<p dir=\"ltr\">Hair serum T&oacute;c M&acirc;y nh&agrave; Cỏ Mềm được nhiều t&iacute;n đồ l&agrave;m đẹp tin d&ugrave;ng bởi hiệu quả dưỡng t&oacute;c su&ocirc;n mượt với sự kết hợp của c&aacute;c th&agrave;nh phần:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Nước tinh khiết (Purified water)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Propanediol</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Vỏ bưởi (Citrus maxima peel essential oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Hydrolyzed Keratin</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chiết xuất Bạch quả l&ecirc;n men</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">DihydroxypropylArginine HCl</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chiết xuất quả M&acirc;m x&ocirc;i (Rubus crateagifolius fruit extract)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Glycerin</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Hương nhu (Ocimum gratissimum essential oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Hoắc hương (Pogostemon cablin essential oil).</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em><strong>Hair serum T&oacute;c M&acirc;y</strong>&nbsp;l&agrave; sản phẩm dưỡng t&oacute;c kh&ocirc;ng thể bỏ qua trong qu&aacute; tr&igrave;nh chăm s&oacute;c t&oacute;c mềm mượt. Nếu bạn đang t&igrave;m kiếm một sản phẩm gi&uacute;p cải thiện t&igrave;nh trạng t&oacute;c xơ rối, g&atilde;y rụng, hair serum T&oacute;c M&acirc;y nh&agrave; Cỏ ch&iacute;nh l&agrave; lựa chọn h&agrave;ng đầu.&nbsp;</em></p>', '171739883020240603141350yiFf0fWU2hZ4Y7X42xwg7syZZCJrChYdHxnmxHQA.webp', 150.00, 210.00, 3, 210.00, 2, 1, 2, 1, 1, '2024-06-03 07:13:50', '2024-06-03 07:15:29');
INSERT INTO `products` (`id`, `name`, `slug`, `code`, `product_category_id`, `manufacturer_id`, `description`, `image`, `price_prime`, `price`, `unit_id`, `price_sale`, `quantity`, `admin_id`, `bought`, `view_count`, `status`, `created_at`, `updated_at`) VALUES
(17, 'Son Ngọc Không Chì', 'son-ngoc-khong-chi-1717438097', 'SP023', 1, 195, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p><em><strong>Son Ngọc</strong>&nbsp;Cỏ Mềm l&agrave; d&ograve;ng son được kiểm nghiệm kh&ocirc;ng chứa ch&igrave; với th&agrave;nh phần thi&ecirc;n nhi&ecirc;n dưỡng cho đ&ocirc;i m&ocirc;i mềm mịn, ngăn ngừa nứt nẻ, l&agrave; thỏi son được nhiều c&ocirc; g&aacute;i tin d&ugrave;ng.</em></p>\r\n\r\n<p><img alt=\"son ngọc\" src=\"https://static.comem.vn/uploads/August2023/son-ngoc-co-mem-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p><em>Son Ngọc Cỏ Mềm kh&ocirc;ng chứa ch&igrave;</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Son Ngọc</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng</td>\r\n			<td>3.8 gram</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảng m&agrave;u son</td>\r\n			<td>04 m&agrave;u</td>\r\n		</tr>\r\n		<tr>\r\n			<td>C&ocirc;ng thức</td>\r\n			<td>Son kh&ocirc;ng chứa ch&igrave;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Th&agrave;nh phần</td>\r\n			<td>Dầu Hạnh nh&acirc;n, dầu hạt T&aacute;o, dầu C&aacute;m gạo, Vitamin E, bơ Oliu, tinh dầu Cam ngọt, m&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n&hellip;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>12 th&aacute;ng. Mở nắp: 6 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật son Ngọc Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Son Ngọc l&agrave; d&ograve;ng son m&ocirc;i trang điểm chứa c&aacute;c th&agrave;nh phần thi&ecirc;n nhi&ecirc;n an to&agrave;n, l&agrave;nh t&iacute;nh, được kiểm nghiệm kh&ocirc;ng chứa ch&igrave;, được nhiều chị em lựa chọn:</p>\r\n\r\n<h3 dir=\"ltr\">Th&agrave;nh phần thi&ecirc;n nhi&ecirc;n</h3>\r\n\r\n<p dir=\"ltr\">Sản phẩm son Ngọc nh&agrave; Cỏ Mềm chứa c&aacute;c th&agrave;nh phần từ thi&ecirc;n nhi&ecirc;n như dầu Hạnh nh&acirc;n, dầu hạt T&aacute;o, dầu C&aacute;m gạo c&oacute; c&ocirc;ng dụng giữ ẩm, dưỡng mềm cho m&ocirc;i, cung cấp dưỡng chất cho m&ocirc;i v&agrave; hỗ trợ giảm th&acirc;m m&ocirc;i hiệu quả. V&igrave; vậy, đ&acirc;y l&agrave; d&ograve;ng son an to&agrave;n cho sức khỏe.</p>\r\n\r\n<p><img alt=\"son ngọc\" src=\"https://static.comem.vn/uploads/August2023/son-ngoc-co-mem-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Son Ngọc c&oacute; th&agrave;nh phần từ thi&ecirc;n nhi&ecirc;n</p>\r\n\r\n<h3 dir=\"ltr\">Mềm mịn, l&acirc;u tr&ocirc;i</h3>\r\n\r\n<p dir=\"ltr\">Sản phẩm chứa c&aacute;c th&agrave;nh phần m&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n đạt ti&ecirc;u chuẩn FDA Hoa Kỳ n&ecirc;n an to&agrave;n, mềm mịn cho m&ocirc;i, giữ cho m&agrave;u son l&acirc;u tr&ocirc;i.</p>\r\n\r\n<h3 dir=\"ltr\">Kh&ocirc;ng chất bảo quản</h3>\r\n\r\n<p dir=\"ltr\">Son Ngọc l&agrave; d&ograve;ng son kh&ocirc;ng chứa c&aacute;c chất bảo quản, kh&ocirc;ng chứa c&aacute;c hương liệu tổng hợp n&ecirc;n an to&agrave;n cho m&ocirc;i, c&ugrave;ng với hương thơm tinh dầu Cam ngọt đem đến cảm gi&aacute;c thoải m&aacute;i khi thoa l&ecirc;n m&ocirc;i.</p>\r\n\r\n<h3 dir=\"ltr\">Bảng m&agrave;u đa dạng</h3>\r\n\r\n<p dir=\"ltr\">Son Ngọc Cỏ Mềm c&oacute; bảng m&agrave;u đa dạng với 4 tone m&agrave;u nổi bật cho n&agrave;ng lựa chọn bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>M&agrave;u 21:</strong>&nbsp;Hồng đất</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>M&agrave;u 22:</strong>&nbsp;Đỏ đất</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>M&agrave;u 23:</strong>&nbsp;Đỏ gạch</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>M&agrave;u 24:</strong>&nbsp;Cam ch&aacute;y</p>\r\n	</li>\r\n</ul>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng son Ngọc</h2>\r\n\r\n<p dir=\"ltr\">Son Ngọc nh&agrave; Cỏ l&agrave; thỏi son được ph&aacute;i đẹp y&ecirc;u th&iacute;ch bởi đ&acirc;y l&agrave; d&ograve;ng son m&ocirc;i kh&ocirc;ng chỉ trang điểm cho m&ocirc;i m&agrave; c&ograve;n dưỡng cho đ&ocirc;i m&ocirc;i mềm mịn, ngăn ngừa nứt nẻ, kh&ocirc;ng l&agrave;m th&acirc;m m&ocirc;i.</p>\r\n\r\n<p><img alt=\"son ngọc\" src=\"https://static.comem.vn/uploads/August2023/son-ngoc-co-mem-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Son Ngọc nh&agrave; Cỏ kh&ocirc;ng l&agrave;m th&acirc;m m&ocirc;i</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần son Ngọc Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">C&aacute;c th&agrave;nh phần thi&ecirc;n nhi&ecirc;n ch&iacute;nh c&oacute; trong thỏi son Ngọc nh&agrave; Cỏ bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Hạnh nh&acirc;n (Prunus dulcis oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu hạt T&aacute;o (Pyrus malus seed oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu C&aacute;m gạo (Oryza sativa bran oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Vitamin E (Tocopherol)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bơ Oliu (Sorbitan olivate)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">S&aacute;p Candelilla (Euphorbia cerifera (candelilla) wax)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Cam ngọt (Citrus sinensis essential oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">M&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em>Nếu bạn đang t&igrave;m kiếm một thỏi son an to&agrave;n với những tone m&agrave;u đẹp, vậy th&igrave; đừng bỏ qua&nbsp;<strong>son Ngọc</strong>&nbsp;nh&agrave; Cỏ Mềm nh&eacute;, nhanh tay cho sản phẩm v&agrave;o giỏ h&agrave;ng để sở hữu em n&oacute; ngay th&ocirc;i n&agrave;o!</em></p>', '171743809720240604010817LFJ9O5Xbu5c7PQS24biznW0SkI174OaVHoVxycav.webp', 200.00, 290.00, 16, 289.00, 99, 1, 1, 0, 1, '2024-06-03 18:08:17', '2024-06-03 18:08:17'),
(18, 'Xịt Thơm Body Mist Colors', 'xit-thom-body-mist-colors-1717438194', 'SP024', 4, 224, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em><strong>Xịt thơm Body Mist</strong>&nbsp;Cỏ Mềm l&agrave; sản phẩm xịt thơm to&agrave;n th&acirc;n, gi&uacute;p khử m&ugrave;i h&ocirc;i kh&oacute; chịu, lưu lại cho bạn hương thơm nhẹ nh&agrave;ng, tinh tế v&agrave; c&ograve;n g&oacute;p phần dưỡng ẩm cho da. Sản phẩm Body Mist nh&agrave; Cỏ Mềm c&oacute; thể sử dụng an to&agrave;n cho cả l&agrave;n da nhạy cảm.</em></p>\r\n\r\n<p><img alt=\"xịt thơm body mist colors\" src=\"https://static.comem.vn/uploads/August2023/xit-thom-body-mist-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p><em>Xịt thơm Body Mist Colors</em></p>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật của Body Mist Colors Cỏ Mềm&nbsp;</h2>\r\n\r\n<p dir=\"ltr\">Hiện nay d&ograve;ng xịt thơm cơ thể Body mist Colors đang được giới trẻ rất ưa chuộng v&igrave; sở hữu nhiều ưu điểm nổi bật. Những nốt hương tự nhi&ecirc;n, nhẹ nh&agrave;ng với khả năng lưu hương l&acirc;u tạo cho bạn một m&ugrave;i hương đặc biệt. Ngo&agrave;i ra, với bảng th&agrave;nh phần l&agrave;nh t&iacute;nh, an to&agrave;n, sản phẩm an to&agrave;n khi sử dụng cho cả những l&agrave;n da nhạy cảm.</p>\r\n\r\n<p><img alt=\"xịt thơm body mist colors\" src=\"https://static.comem.vn/uploads/August2023/xit-thom-body-mist-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Xịt thơm Body mist Colors of Pear &amp; Apricot</p>\r\n\r\n<h2 dir=\"ltr\">Ph&acirc;n loại c&aacute;c loại xịt thơm Body mist Colors</h2>\r\n\r\n<p dir=\"ltr\">Hiện tại bộ sản phẩm Body mist Colors c&oacute; 3 d&ograve;ng ch&iacute;nh l&agrave;:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Colors of Pear &amp; Apricot (hương L&ecirc; v&agrave; hoa Mơ).</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Colors of White Flowers (hương những lo&agrave;i hoa trắng).</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Colors of Patchouli (hương Gỗ ngọt, Hoắc hương).&nbsp;</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\">Body mist m&ugrave;i n&agrave;o thơm nhất? Mỗi chai xịt thơm cơ thể lại mang trong m&igrave;nh những sắc hương kh&aacute;c nhau. Cụ thể, 3 d&ograve;ng Body mist sắc m&agrave;u c&oacute; những tầng hương ch&iacute;nh như sau:</p>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Colors</th>\r\n			<th>Colors of Pear &amp; Apricot (Sắc hương của Tr&aacute;i l&ecirc; v&agrave; Hoa mơ)</th>\r\n			<th>Colors of White Flowers (Sắc hương của những lo&agrave;i hoa trắng)</th>\r\n			<th>Colors of Patchouli (Sắc hương của Gỗ ngọt, Hoắc hương)</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>Hương đầu</strong></td>\r\n			<td>Mandarin (qu&yacute;t hồng), Pear (quả l&ecirc;)</td>\r\n			<td>White Flowers (hoa trắng)</td>\r\n			<td>Cam Bergamot, Aqueous (hương nước)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hương giữa</strong></td>\r\n			<td>Apricot (quả mơ), Apple (quả t&aacute;o), Aloe (l&ocirc; hội)</td>\r\n			<td>Tuberose (hoa huệ), Jasmine (hoa nh&agrave;i)</td>\r\n			<td>Lily Of The Valley (hoa linh lan)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hương cuối</strong></td>\r\n			<td>Cedarwood (tuyết t&ugrave;ng), Rosewood (gỗ hồng)</td>\r\n			<td>Sandalwood (ho&agrave;ng đ&agrave;n), Musk (xạ hương)</td>\r\n			<td>Patchouli (hoắc hương), Moss (r&ecirc;u)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>M&agrave;u</strong></td>\r\n			<td>Dung dịch v&agrave;ng cam</td>\r\n			<td>Dung dịch hồng nhạt</td>\r\n			<td>Dung dịch xanh l&aacute;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Độ lưu hương</strong></td>\r\n			<td>3-4h</td>\r\n			<td>3-4h</td>\r\n			<td>4-5h</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Phong c&aacute;ch</strong></td>\r\n			<td>Tươi m&aacute;t, ngọt ng&agrave;o</td>\r\n			<td>Duy&ecirc;n d&aacute;ng, quyến rũ</td>\r\n			<td>C&aacute; t&iacute;nh, s&acirc;u sắc</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng của Body mist Colors Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Với những hương nước hoa tươi m&aacute;t từ hoa l&ecirc; v&agrave; quả mơ, trong veo của hoa trắng v&agrave; đậm ngọt từ hương gỗ, sản phẩm gi&uacute;p khử m&ugrave;i h&ocirc;i kh&oacute; chịu, lưu lại cho cơ thể hương thơm tinh tế, nhẹ nh&agrave;ng. Ngo&agrave;i ra, chiết xuất từ l&ocirc; hội g&oacute;p phần dưỡng ẩm cho da. Nếu bạn c&oacute; l&agrave;n da nhạy cảm, cũng đừng lo lắng, Body mist Colors c&oacute; thể sử dụng an to&agrave;n cho l&agrave;n da bạn.</p>\r\n\r\n<p><img alt=\"xịt thơm body mist colors\" src=\"https://static.comem.vn/uploads/August2023/xit-thom-body-mist-4.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Xịt thơm Body Mist Colors of White Flowers</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần của Body mist Colors</h2>\r\n\r\n<p dir=\"ltr\">Xịt thơm Body mist Colors nh&agrave; Cỏ l&agrave; d&ograve;ng sản phẩm c&oacute; chiết xuất từ th&agrave;nh phần quen thuộc, an to&agrave;n n&ecirc;n c&oacute; thể d&ugrave;ng cho những l&agrave;n da nhạy cảm với:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Ethanol</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Purified water (Nước tinh khiết)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Fragrance</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Glycerin</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Aloe vera extract (Chiết xuất l&ocirc; hội)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">CI 15985/ CI 19140/ CI 42090/ CI 17200.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"xịt thơm body mist colors\" src=\"https://static.comem.vn/uploads/August2023/xit-thom-body-mist-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Xịt thơm Body mist Colors of Patchouli</p>\r\n\r\n<p dir=\"ltr\"><em><strong>Bộ xịt thơm Body mist Colors</strong>&nbsp;l&agrave; lựa chọn tuyệt vời để mang đến cho cơ thể hương thơm thi&ecirc;n nhi&ecirc;n dễ chịu. C&aacute;c chị em h&atilde;y nhanh tay đặt mua sản phẩm tại Cỏ Mềm để c&oacute; cơ hội trải nghiệm loại xịt thơm cơ thể chất lượng n&agrave;y nh&eacute;!</em></p>', '171743819420240604010954utNWPBKrHR5VsJiCheODTi7WO1TouBgobACkEhsp.webp', 150.00, 210.00, 11, 200.00, 15, 1, 4, 3, 1, '2024-06-03 18:09:54', '2024-06-08 08:32:50'),
(19, 'Kem Má Hồng Hây Hây', 'kem-ma-hong-hay-hay-1717438291', 'SP025', 1, 218, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em><strong>Kem m&aacute; hồng H&acirc;y H&acirc;y</strong>&nbsp;l&agrave; d&ograve;ng kem trang điểm gi&uacute;p gương mặt trở n&ecirc;n tươi tắn v&agrave; rạng rỡ, cho bạn một makeup look ho&agrave;n hảo nhất. Với kết cấu kem mỏng nhẹ, hiệu ứng bắt s&aacute;ng tốt, kem m&aacute; hồng chinh phục được nhiều t&iacute;n đồ l&agrave;m đẹp.</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Kem m&aacute; hồng H&acirc;y H&acirc;y</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thể chất</td>\r\n			<td>Dạng kem thỏi</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Kết cấu</td>\r\n			<td>Mỏng nhẹ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Ph&acirc;n loại</td>\r\n			<td>01 (Quả đ&agrave;o), 02 (Quả hồng)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng</td>\r\n			<td>5g</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Th&agrave;nh phần</td>\r\n			<td>M&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n, dầu hạnh nh&acirc;n, dầu c&aacute;m gạo, s&aacute;p ong, s&aacute;p đậu n&agrave;nh, bơ hạt mỡ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảo quản</td>\r\n			<td>Nơi kh&ocirc; m&aacute;t. Tr&aacute;nh nắng n&oacute;ng v&agrave; nguồn nhiệt</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>18 th&aacute;ng. Mở nắp: 6 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật kem m&aacute; hồng H&acirc;y H&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Kem m&aacute; hồng H&acirc;y H&acirc;y l&agrave; sản phẩm kem trang điểm cho v&ugrave;ng g&ograve; m&aacute;, gi&uacute;p gương mặt trở n&ecirc;n tươi tắn v&agrave; rạng rỡ hơn, được nhiều chị em y&ecirc;u th&iacute;ch với c&aacute;c ưu điểm nổi bật:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Kết cấu kem mỏng nhẹ, tự nhi&ecirc;n, dễ t&aacute;n, tạo n&ecirc;n lớp m&aacute; hồng tươi s&aacute;ng cho v&ugrave;ng g&ograve; m&aacute;, gi&uacute;p gương mặt th&ecirc;m rạng rỡ.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">M&agrave;u ngọc trai tạo n&ecirc;n hiệu ứng lấp l&aacute;nh, bắt s&aacute;ng tốt, gi&uacute;p gương mặt trở n&ecirc;n nổi bật.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"kem má hồng hây hây\" src=\"https://static.comem.vn/uploads/August2023/kem-ma-hong-hay-hay-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem m&aacute; hồng H&acirc;y H&acirc;y c&oacute; kết cấu mỏng nhẹ</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Gồm c&oacute; 2 m&agrave;u cho bạn lựa chọn:&nbsp;</p>\r\n	</li>\r\n</ul>\r\n\r\n<ol>\r\n	<li dir=\"ltr\"><strong>Kem m&aacute; hồng H&acirc;y H&acirc;y 01 (Quả đ&agrave;o)</strong></li>\r\n	<li dir=\"ltr\"><strong>Kem m&aacute; hồng H&acirc;y H&acirc;y 02 (Quả hồng)</strong></li>\r\n</ol>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng kem m&aacute; hồng H&acirc;y H&acirc;y Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Kem m&aacute; hồng H&acirc;y H&acirc;y nh&agrave; Cỏ l&agrave; sản phẩm gi&uacute;p trang điểm cho v&ugrave;ng g&ograve; m&aacute;, từ đ&oacute; gi&uacute;p cho gương mặt tươi tắn v&agrave; rạng rỡ hơn.</p>\r\n\r\n<p><img alt=\"kem má hồng hây hây\" src=\"https://static.comem.vn/uploads/August2023/kem-ma-hong-hay-hay-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Kem m&aacute; hồng H&acirc;y H&acirc;y gi&uacute;p gương mặt tươi tắn</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần kem m&aacute; hồng H&acirc;y H&acirc;y</h2>\r\n\r\n<p dir=\"ltr\">Kem m&aacute; hồng H&acirc;y H&acirc;y gi&uacute;p gương mặt trở n&ecirc;n rạng rỡ hơn với c&aacute;c th&agrave;nh phần ch&iacute;nh bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Hạnh nh&acirc;n (Prunus dulcis oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu C&aacute;m gạo (Oryza sativa bran oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bột Gạo (Oryza sativa (rice) powder)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">S&aacute;p Ong (Bees wax)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">S&aacute;p Đậu n&agrave;nh (Hydrogenated soybean oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bơ Hạt mỡ (Butyrospermum parkii butter)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">M&agrave;u kho&aacute;ng thi&ecirc;n nhi&ecirc;n</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">M&agrave;u ngọc trai</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">S&aacute;p Candelilla (Euphorbia cerifera (candelilla) wax)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tocopherol (Vitamin E).</p>\r\n	</li>\r\n</ul>', '171743829120240604011131iWWwTaxRAKNyLTylRzl05zvXYGrLjZgQ7YhBDZlY.webp', 100.00, 139.00, 12, 138.00, 38, 1, 2, 2, 1, '2024-06-03 18:11:31', '2024-06-08 04:54:10'),
(20, 'Dầu Rửa Mặt 3S', 'dau-rua-mat-3s-1717438390', 'SP026', 2, 224, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p dir=\"ltr\"><em><strong>Dầu rửa mặt 3S</strong>&nbsp;l&agrave; sản phẩm được sử dụng h&agrave;ng ng&agrave;y gi&uacute;p l&agrave;m sạch da v&agrave; se kh&iacute;t lỗ ch&acirc;n l&ocirc;ng hiệu quả. Khi rửa mặt bằng dầu kết hợp với c&aacute;c động t&aacute;c massage gi&uacute;p l&agrave;n da đ&agrave;n hồi v&agrave; khỏe mạnh.</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Dầu rửa mặt 3S</td>\r\n		</tr>\r\n		<tr>\r\n			<td>H&igrave;nh dạng</td>\r\n			<td>Vỏ nhựa trong c&oacute; nh&atilde;n d&aacute;n</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dung t&iacute;ch</td>\r\n			<td>50ml</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thể chất</td>\r\n			<td>Dạng dầu</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Th&agrave;nh phần</td>\r\n			<td>Dầu thầu dầu, dầu oliu, dầu quả bơ, dầu hạt nho, chất nhũ h&oacute;a, tinh dầu cam ngọt, tinh dầu chanh sần</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảo quản</td>\r\n			<td>Bảo quản nơi kh&ocirc; m&aacute;t, tr&aacute;nh &aacute;nh nắng v&agrave; nguồn nhiệt</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>18 th&aacute;ng. Mở nắp: 6 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật dầu rửa mặt 3S</h2>\r\n\r\n<p dir=\"ltr\">Dầu rửa mặt 3S l&agrave; bước đầu ti&ecirc;n trong phương ph&aacute;p rửa mặt 2 bước, bằng phương ph&aacute;p d&ugrave;ng ch&iacute;nh gốc dầu để h&ograve;a tan ho&agrave;n to&agrave;n rồi nhũ h&oacute;a cuốn tr&ocirc;i đi bụi bẩn, b&atilde; nhờn, mỹ phẩm c&ograve;n lưu lại tr&ecirc;n da.&nbsp;</p>\r\n\r\n<p dir=\"ltr\">Đ&acirc;y ch&iacute;nh l&agrave; b&iacute; quyết cho l&agrave;n da S&Aacute;NG - SẠCH - SE kh&iacute;t lỗ ch&acirc;n l&ocirc;ng với c&aacute;c th&agrave;nh phần hiệu quả:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Th&agrave;nh phần từ c&aacute;c loại dầu thực vật tạo n&ecirc;n hỗn hợp c&acirc;n bằng thể chất gi&uacute;p h&ograve;a tan nhanh ch&oacute;ng lớp dầu thừa v&agrave; mỹ phẩm c&ograve;n lại tr&ecirc;n da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Hạt nho, dầu Oliu, dầu Quả bơ: chứa dưỡng chất v&agrave; chất chống oxy h&oacute;a gi&uacute;p l&agrave;n da mềm mại, s&aacute;ng khỏe.&nbsp;</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Chanh sần v&agrave; Cam ngọt c&oacute; t&aacute;c dụng l&agrave;m sạch, kh&aacute;ng khuẩn, chống oxy h&oacute;a, ngừa n&aacute;m cho da.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"dầu rửa mặt 3s\" src=\"https://static.comem.vn/uploads/August2023/dau-rua-mat-3s-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Th&agrave;nh phần dầu rửa mặt 3S</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng dầu rửa mặt 3S</h2>\r\n\r\n<h3 dir=\"ltr\">L&agrave;m sạch da</h3>\r\n\r\n<p dir=\"ltr\">Dầu rửa mặt 3S c&oacute; th&agrave;nh phần từ c&aacute;c loại dầu thực vật gi&uacute;p l&agrave;m sạch lớp trang điểm v&agrave; bụi bẩn, loại bỏ b&atilde; nhờn tr&ecirc;n da.</p>\r\n\r\n<h3 dir=\"ltr\">Se kh&iacute;t lỗ ch&acirc;n l&ocirc;ng</h3>\r\n\r\n<p dir=\"ltr\">B&ecirc;n cạnh c&ocirc;ng dụng l&agrave;m sạch cho da, sản phẩm dầu rửa mặt 3S c&ograve;n g&oacute;p phần se kh&iacute;t lỗ ch&acirc;n l&ocirc;ng cho da.</p>\r\n\r\n<p><img alt=\"dầu rửa mặt 3s\" src=\"https://static.comem.vn/uploads/August2023/dau-rua-mat-3s-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>C&ocirc;ng dụng dầu rửa mặt 3S</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần dầu rửa mặt 3S</h2>\r\n\r\n<p dir=\"ltr\">Dầu rửa mặt 3S c&oacute; chứa c&aacute;c th&agrave;nh phần ch&iacute;nh sau đ&acirc;y:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Thầu dầu (Ricinus communis oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Oliu (Olea europaea oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Quả bơ (Persea gratissima oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Dầu Hạt nho (Vitis vinifera seed oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chất nhũ h&oacute;a (Polysorbate 80 &amp; Polysorbate 20)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Cam ngọt (Citrus sinensis essential oil)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Chanh sần (Citrus aurantifolia essential oil).</p>\r\n	</li>\r\n</ul>', '171743839020240604011310FxA1Og874G8imfcHmKfrcT0HOmwZ1uWe1cF4XilC.webp', 120.00, 170.00, 11, 150.00, 10, 1, 0, 2, 1, '2024-06-03 18:13:10', '2024-06-08 04:54:19'),
(21, 'Bột Rửa Mặt Taptap', 'bot-rua-mat-taptap-1717952690', 'SP0030', 2, 230, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p><em><strong>Bột rửa mặt Taptap</strong>&nbsp;l&agrave; dạng bột thảo mộc rửa mặt gi&uacute;p l&agrave;m sạch bụi bẩn tr&ecirc;n da đồng thời gi&uacute;p tẩy tế b&agrave;o chết một c&aacute;ch nhẹ nh&agrave;ng cho da, hỗ trợ l&agrave;m giảm mụn đầu đen v&agrave; mụn c&aacute;m.</em></p>\r\n\r\n<p><img alt=\"bột rửa mặt taptap\" src=\"https://static.comem.vn/uploads/August2023/bot-rua-mat-taptap-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p><em>Bột rửa mặt Taptap gi&uacute;p l&agrave;m sạch da</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Bột rửa mặt Taptap</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Vấn đề của da</td>\r\n			<td>L&agrave;n da đang gặp phải t&igrave;nh trạng mụn đầu đen v&agrave; mụn c&aacute;m</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dạng sản phẩm</td>\r\n			<td>Dạng chai thủy tinh</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng</td>\r\n			<td>50 gram</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảo quản</td>\r\n			<td>Bảo quản bột rửa mặt nơi tho&aacute;ng m&aacute;t, kh&ocirc; r&aacute;o. Cần đậy k&iacute;n nắp sau khi d&ugrave;ng, v&agrave; tr&aacute;nh để nước rơi v&agrave;o sản phẩm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>12 th&aacute;ng. Mở nắp: 2 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật của bột rửa mặt Taptap</h2>\r\n\r\n<p dir=\"ltr\">Bột rửa mặt Taptap được nhiều người y&ecirc;u th&iacute;ch bởi sản phẩm c&oacute; th&agrave;nh phần từ bột thảo mộc gi&agrave;u vitamin B gi&uacute;p duy tr&igrave; l&agrave;n da khoẻ mịn hồng h&agrave;o với:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Bột C&aacute;m gạo:</strong>&nbsp;Chống oxy h&oacute;a cung cấp dưỡng chất cho da gi&uacute;p da khỏe mạnh</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Bột Yến mạch:</strong>&nbsp;Th&ocirc; mịn nhẹ nh&agrave;ng lấy đi c&aacute;c tế b&agrave;o da chết, gi&uacute;p cải thiện t&igrave;nh trạng mụn ẩn, mụn đầu đen đồng thời gi&uacute;p duy tr&igrave; độ ẩm cho da</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\"><strong>Bột Tr&agrave; xanh v&agrave; bột Bạch chỉ:</strong>&nbsp;Hỗ trợ l&agrave;m s&aacute;ng da, gi&uacute;p ngăn ngừa l&atilde;o ho&aacute; v&agrave; kiềm dầu cho da.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"bột rửa mặt taptap\" src=\"https://static.comem.vn/uploads/August2023/bot-rua-mat-taptap-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Bột rửa mặt Taptap chứa thảo mộc gi&agrave;u vitamin B</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng của bột rửa mặt Taptap</h2>\r\n\r\n<p dir=\"ltr\">Bột rửa mặt Taptap bạn pha với nước để rửa mặt, l&agrave;m sạch b&atilde; nhờn tr&ecirc;n da, nhẹ nh&agrave;ng lấy đi lớp tế b&agrave;o da chết, gi&uacute;p l&agrave;n da mịn m&agrave;ng s&aacute;ng khỏe. Sử dụng bột rửa mặt Taptap g&oacute;p phần giảm v&agrave; ngăn ngừa mụn đầu đen, mụn c&aacute;m.</p>\r\n\r\n<p><img alt=\"bột rửa mặt taptap\" src=\"https://static.comem.vn/uploads/August2023/bot-rua-mat-taptap-1.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>L&agrave;m sạch da với bột rửa mặt Taptap</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần bột rửa mặt Taptap</h2>\r\n\r\n<p dir=\"ltr\">Sản phẩm chứa c&aacute;c th&agrave;nh phần ch&iacute;nh từ bột thảo mộc như:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bột Đậu xanh (Vigna radiata seed powder)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bột Đậu đỏ (Vigna angularis seed powder)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bột Yến mạch (Avena sativa kernel powder)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bột C&aacute;m gạo (Oryza sativa bran powder)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bột Tr&agrave; xanh (Camellia sinensis leaf powder)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Bột Bạch chỉ (Angelica dahurica root powder).</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em>L&agrave;m sạch da l&agrave; bước đầu ti&ecirc;n trong chu tr&igrave;nh chăm s&oacute;c da h&agrave;ng ng&agrave;y n&ecirc;n cần được ch&uacute; trọng.&nbsp;<strong>Bột rửa mặt Taptap</strong>&nbsp;l&agrave; sản phẩm gi&uacute;p l&agrave;m sạch cho da, cải thiện t&igrave;nh trạng mụn đầu đen v&agrave; mụn c&aacute;m, cho bạn l&agrave;n da s&aacute;ng khỏe.</em></p>', '171795269020240610000450t3meC5VNFiE8wdNEgv2x2x96sNNnBNML2hkWTsLi.webp', 50.00, 90.00, 3, 90.00, 9, 1, 0, 1, 1, '2024-06-09 17:04:50', '2024-06-09 17:13:20'),
(22, 'Chấm Mụn Rau Má', 'cham-mun-rau-ma-1717952839', 'SP0031', 2, 214, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p><em><strong>Chấm mụn Rau M&aacute;</strong>&nbsp;l&agrave; sản phẩm chấm mụn thuộc bộ dưỡng da rau m&aacute; nh&agrave; Cỏ Mềm ngăn ngừa mụn tr&ecirc;n da, g&oacute;p phần l&agrave;m mờ c&aacute;c vết th&acirc;m do mụn. Đ&acirc;y l&agrave; b&iacute; quyết trị mụn được c&aacute;c chị em tin d&ugrave;ng v&agrave; ưa chuộng.</em></p>\r\n\r\n<p><img alt=\"chấm mụn rau má\" src=\"https://static.comem.vn/uploads/August2023/cham-mun-rau-ma-4.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p><em>Chấm mụn Rau M&aacute; Cỏ Mềm</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Chấm mụn Rau M&aacute;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thể chất</td>\r\n			<td>Dạng gel lỏng</td>\r\n		</tr>\r\n		<tr>\r\n			<td>M&ugrave;i</td>\r\n			<td>M&ugrave;i tr&agrave;m tr&agrave; đặc trưng</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Khối lượng</td>\r\n			<td>10g</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Đối tượng sử dụng</td>\r\n			<td>Người c&oacute; t&igrave;nh trạng mụn tr&ecirc;n da</td>\r\n		</tr>\r\n		<tr>\r\n			<td>C&ocirc;ng dụng</td>\r\n			<td>Gi&uacute;p ngăn ngừa v&agrave; cải thiện t&igrave;nh trạng mụn tr&ecirc;n da</td>\r\n		</tr>\r\n		<tr>\r\n			<td>C&aacute;ch d&ugrave;ng</td>\r\n			<td>Lấy một lượng vừa đủ, b&ocirc;i v&agrave;o vết mụn v&agrave; v&ugrave;ng xung quanh 2-3 lần/ ng&agrave;y</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>24 th&aacute;ng. Mở nắp: 12 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật chấm mụn Rau M&aacute; Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Chấm mụn Rau M&aacute; l&agrave; d&ograve;ng sản phẩm ngăn ngừa mụn hiệu quả với c&aacute;c th&agrave;nh phần ch&iacute;nh nhiều ưu điểm nổi bật cho da:&nbsp;</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Chiết xuất Rau m&aacute;: Gi&uacute;p cải thiện t&igrave;nh trạng mụn vi&ecirc;m v&agrave; giữ ẩm cho da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Niacinamide (Vitamin B3): Gi&uacute;p l&agrave;m s&aacute;ng da, l&agrave;m mờ c&aacute;c vết th&acirc;m tr&ecirc;n da, gi&uacute;p cải thiện độ đ&agrave;n hồi cho da.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Piroctone Olamine: Gi&uacute;p cải thiện t&igrave;nh trạng mụn tr&ecirc;n da.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"chấm mụn rau má\" src=\"https://static.comem.vn/uploads/August2023/cham-mun-rau-ma-5.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Chấm mụn Rau M&aacute; cải thiện t&igrave;nh trạng mụn vi&ecirc;m</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng chấm mụn Rau M&aacute; nh&agrave; Cỏ</h2>\r\n\r\n<p dir=\"ltr\">Chấm mụn Rau M&aacute; Cỏ Mềm được sử dụng l&agrave;m sản phẩm chấm mụn gi&uacute;p dưỡng da, ngăn ngừa v&agrave; cải thiện t&igrave;nh trạng mụn tr&ecirc;n da, g&oacute;p phần l&agrave;m mờ c&aacute;c vết th&acirc;m do mụn để lại, cho l&agrave;n da mềm mịn, khỏe mạnh.</p>\r\n\r\n<p><img alt=\"chấm mụn rau má\" src=\"https://static.comem.vn/uploads/August2023/cham-mun-rau-ma-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Sản phẩm g&oacute;p phần l&agrave;m mờ c&aacute;c vết th&acirc;m do mụn</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần chấm mụn Rau M&aacute;</h2>\r\n\r\n<p dir=\"ltr\">Sản phẩm chấm mụn Rau M&aacute; chứa c&aacute;c th&agrave;nh phần ch&iacute;nh gi&uacute;p cải thiện t&igrave;nh trạng mụn tr&ecirc;n da bao gồm:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Purified water (Nước tinh khiết)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Niacinamide</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Potassium Azeloyl Diglycinate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Acetyl Glucosamine</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Cyclodextrin (and) Centella Asiatica extract</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">1,2-Hexanediol</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Melaleuca Alternifolia essential oil</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">PEG- 40 hydrogenated castor oil</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Glycerin (and) Water (and) Polylysine</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Piroctone Olamine</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Xanthan gum</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Citric acid.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em>Nếu bạn đang gặp c&aacute;c vấn đề về mụn vi&ecirc;m, bọc, đừng ngần ngại m&agrave; h&atilde;y thử ngay&nbsp;<strong>chấm mụn Rau M&aacute; Cỏ Mềm</strong>. Tham khảo sản phẩm tr&ecirc;n website hoặc li&ecirc;n hệ trực tiếp với Cỏ để được tư vấn kỹ nhất về sản phẩm nh&eacute;!</em></p>', '171795283920240610000719tbxAkQLzanSofIeMp6AuIdVNQTGRjmxFXWWzo9jc.webp', 130.00, 165.00, 11, 165.00, 1, 1, 0, 1, 1, '2024-06-09 17:07:19', '2024-06-15 08:41:10'),
(23, 'Dầu Gội Sạch Gàu Cỏ Mềm', 'dau-goi-sach-gau-co-mem-1717953022', 'SP0032', 3, 224, '<h2>TH&Ocirc;NG TIN SẢN PHẨM</h2>\r\n\r\n<p><em><strong>Dầu gội sạch g&agrave;u Cỏ Mềm</strong>&nbsp;với chiết xuất từ cao quả bồ kết, l&aacute; neem, kh&ocirc;ng chứa c&aacute;c chất tạo bọt gốc Paraben gi&uacute;p l&agrave;m sạch t&oacute;c v&agrave; da dầu, ngăn ngừa t&igrave;nh trạng g&agrave;u, ngứa, đem đến m&aacute;i t&oacute;c mềm mượt v&agrave; chắc khỏe.</em></p>\r\n\r\n<h2 dir=\"ltr\">Th&ocirc;ng số sản phẩm</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Th&ocirc;ng số</th>\r\n			<th>Nội dung</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n sản phẩm</td>\r\n			<td>Dầu gội sạch g&agrave;u Cỏ Mềm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dạng sản phẩm</td>\r\n			<td>Dạng chai k&egrave;m chốt chặn th&ocirc;ng minh tiện dụng</td>\r\n		</tr>\r\n		<tr>\r\n			<td>M&ugrave;i hương</td>\r\n			<td>Hương thơm dịu nhẹ, tự nhi&ecirc;n</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dung t&iacute;ch</td>\r\n			<td>250ml</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Loại t&oacute;c ph&ugrave; hợp</td>\r\n			<td>Ph&ugrave; hợp với mọi loại t&oacute;c v&agrave; da dầu</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hạn sử dụng</td>\r\n			<td>2 năm. Mở nắp: 12 th&aacute;ng</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h2 dir=\"ltr\">Ưu điểm nổi bật dầu gội sạch g&agrave;u Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Sản phẩm dầu gội sạch g&agrave;u Cỏ Mềm l&agrave; sản phẩm y&ecirc;u th&iacute;ch của nhiều người bởi c&aacute;c ưu điểm nổi bật như:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Cao quả bồ kết v&agrave; cao dược liệu: Gừng, N&uacute;c n&aacute;c, L&aacute; Neem, Ngũ Sắc, Mần Trầu, D&acirc;u Tằm gi&uacute;p l&agrave;m sạch da đầu, ngăn ngừa g&agrave;u ngứa, l&agrave;m mềm mượt t&oacute;c.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Vitamin B5 (Panthenol) gi&uacute;p giữ ẩm cho t&oacute;c v&agrave; da đầu, hạn chế t&igrave;nh trạng kh&ocirc; da đầu, giảm bong tr&oacute;c k&iacute;ch ứng.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Piroctone Olamine gi&uacute;p ngăn ngừa sự ph&aacute;t triển của vi khuẩn, gi&uacute;p giảm t&igrave;nh trạng g&agrave;u v&agrave; ngứa tr&ecirc;n da đầu.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">BHA (Salicylic acid) gi&uacute;p l&agrave;m sạch tế b&agrave;o da chết nhẹ nh&agrave;ng.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Tinh dầu Bạc h&agrave; v&agrave; tinh dầu Gừng gi&uacute;p kh&aacute;ng khuẩn, tạo m&ugrave;i thơm.</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Sản phẩm kh&ocirc;ng chứa Paraben, m&agrave;u tổng hợp, h&oacute;a chất độc hại n&ecirc;n an to&agrave;n cho da đầu.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><img alt=\"dầu gội sạch gàu\" src=\"https://static.comem.vn/uploads/August2023/dau-goi-sach-gau-co-mem-2.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Dầu gội sạch g&agrave;u Cỏ Mềm gi&uacute;p t&oacute;c mềm mượt chắc khỏe</p>\r\n\r\n<h2 dir=\"ltr\">C&ocirc;ng dụng dầu gội sạch g&agrave;u Cỏ Mềm</h2>\r\n\r\n<p dir=\"ltr\">Dầu gội sạch g&agrave;u Cỏ Mềm c&oacute; c&ocirc;ng dụng trong việc l&agrave;m sạch t&oacute;c v&agrave; da đầu, ngăn ngừa v&agrave; cải thiện t&igrave;nh trạng g&agrave;u, ngứa da đầu. Từ đ&oacute; gi&uacute;p giảm dầu nhờn tr&ecirc;n t&oacute;c, cho m&aacute;i t&oacute;c mềm mượt v&agrave; chắc khỏe hơn.</p>\r\n\r\n<p><img alt=\"dầu gội sạch gàu\" src=\"https://static.comem.vn/uploads/August2023/dau-goi-sach-gau-co-mem-3.jpg\" style=\"height:600px; width:600px\" /></p>\r\n\r\n<p>Dầu gội sạch g&agrave;u Cỏ Mềm gi&uacute;p giảm dầu nhờn tr&ecirc;n t&oacute;c</p>\r\n\r\n<h2 dir=\"ltr\">Th&agrave;nh phần của sản phẩm</h2>\r\n\r\n<p dir=\"ltr\">Dầu gội sạch g&agrave;u Cỏ Mềm gi&uacute;p giải quyết c&aacute;c t&igrave;nh trạng g&agrave;u ngứa da đầu, cho bạn một m&aacute;i t&oacute;c mềm mượt từ b&ecirc;n trong với c&aacute;c th&agrave;nh phần ch&iacute;nh như:</p>\r\n\r\n<ul>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Purified water (Nước tinh khiết)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Gleditsia Triacanthos fruit extract (Cao quả bồ kết)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Cao dược liệu: Gừng, N&uacute;c n&aacute;c, L&aacute; Neem, Ngũ Sắc, Mần Trầu, D&acirc;u Tằm</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Cocamidopropyl Betaine</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">PEG-120 Methyl Glucose Dioleate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Salicylic acid (BHA)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">PEG-7 Glyceryl Cocoate</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Panthenol (Vitamin B5)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Mentha Arvensis essential oil (Tinh dầu Bạc H&agrave;)</p>\r\n	</li>\r\n	<li dir=\"ltr\">\r\n	<p dir=\"ltr\">Zingiber Officinale essential oil (Tinh dầu Gừng).</p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><em><strong>Dầu gội sạch g&agrave;u Cỏ Mềm</strong>&nbsp;xứng đ&aacute;ng l&agrave; lựa chọn h&agrave;ng đầu cho những m&aacute;i t&oacute;c đang gặp phải vấn đề về g&agrave;u, ngứa. V&igrave; thế, nếu bạn đang t&igrave;m kiếm một sản phẩm gội đầu l&agrave;m sạch t&oacute;c v&agrave; da đầu, cho m&aacute;i t&oacute;c chắc khỏe, đừng bỏ qua m&agrave; h&atilde;y thử ngay dầu gội sạch g&agrave;u Cỏ Mềm nh&eacute;!</em></p>', '171795302220240610001022cv8TPzApkD6EsxovtGyF7IbPhDpEiqMUXOeLntis.webp', 200.00, 225.00, 3, 210.00, 4, 1, 0, 1, 1, '2024-06-09 17:10:22', '2024-06-15 08:39:44');

